async def _mark_logged_exchange_preempted(
    exchange_id: str | None,
    *,
    reason: str,
) -> None:
    """Fence a superseded turn without recording invented assistant speech."""

    if not exchange_id:
        return
    async with _chat_memory_state._get_convo_lock():
        for entry in reversed(_conversation_log):
            if str(entry.get("id") or "") != str(exchange_id):
                continue
            entry["status"] = "preempted"
            entry["aura"] = ""
            entry["completed_at"] = _chat_preflight._utc_now_iso()
            entry["preemption_reason"] = str(reason or "foreground_chat_preempted")[:80]
            return


async def _emit_chat_output_receipt(
    reply_text: str,
    *,
    cause: str,
    origin: str = "api",
    target: str = "primary",
    metadata: dict[str, Any] | None = None,
) -> None:
    """Record direct chat replies as durable output receipts."""
    try:
        from core.runtime.executors import run_durable_receipt_io
        from core.runtime.receipts import OutputReceipt, get_receipt_store

        digest = digest_output_content(reply_text)
        receipt = OutputReceipt(
            cause=str(cause or "chat_response"),
            origin=str(origin or "api"),
            target=str(target or "primary"),
            digest=digest,
            metadata=dict(metadata or {}),
        )
        await run_durable_receipt_io(
            get_receipt_store().emit,
            receipt,
            timeout_s=10.0,
            label="chat_output_receipt",
        )
        if str(target or "primary") == "primary":
            try:
                from core.epistemics.epistemic_reach import (
                    acknowledge_epistemic_correction_delivery,
                )

                acknowledge_epistemic_correction_delivery(reply_text)
            except _CHAT_RECOVERABLE_ERRORS as correction_exc:
                record_degradation("chat", correction_exc)
                logger.debug(
                    "Epistemic correction delivery acknowledgement skipped: %s",
                    correction_exc,
                )
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Chat output receipt emit skipped: %s", exc)


async def _shed_generation_for_memory_pressure(reason: str) -> None:
    """Best-effort bounded cleanup before refusing heavy foreground work."""

    try:
        gate = ServiceContainer.get("inference_gate", default=None)
        if gate is not None and hasattr(gate, "_shed_background_workers_for_memory_pressure"):
            result = gate._shed_background_workers_for_memory_pressure(
                reason=str(reason or "foreground_memory_pressure_guard")
            )
            if inspect.isawaitable(result):
                await asyncio.wait_for(result, timeout=2.5)
        import gc

        gc.collect()
    except TimeoutError:
        logger.warning("Timed out shedding background workers under memory pressure.")
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Memory-pressure worker shedding unavailable: %s", exc)


def _required_foreground_memory_snapshot() -> Any:
    """Read one complete memory admission decision or fail closed."""

    from core.utils.memory_monitor import get_memory_pressure_snapshot

    snapshot = get_memory_pressure_snapshot()
    if snapshot is None or not all(
        hasattr(snapshot, field)
        for field in ("critical", "refuse_heavy_local_generation", "reason")
    ):
        raise RuntimeError("foreground memory pressure probe returned no decision")
    if not isinstance(snapshot.critical, bool) or not isinstance(
        snapshot.refuse_heavy_local_generation,
        bool,
    ):
        raise RuntimeError("foreground memory pressure decision is malformed")
    return snapshot


async def _foreground_memory_admission_response(
    *,
    is_benchmark: bool,
    phase: str,
) -> JSONResponse | None:
    """Admit heavy local generation from fresh evidence under lane custody."""

    try:
        snapshot = _required_foreground_memory_snapshot()
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation(
            "chat.memory_admission",
            exc,
            severity="warning",
            action="refused heavy foreground generation without a measured memory decision",
            extra={"phase": str(phase or "foreground")},
        )
        return JSONResponse(
            {
                "response": (
                    "I could not verify enough memory headroom to start the local "
                    "model lane safely, so I stopped before generation."
                ),
                "status": "memory_pressure_probe_unavailable",
                "conversation_lane": _chat_preflight._collect_conversation_lane_status(),
                "memory_pressure": {
                    "measured": False,
                    "phase": str(phase or "foreground"),
                },
                "response_confidence": "guarded",
            },
            status_code=503 if is_benchmark else 200,
        )

    if snapshot.critical:
        live_state = _chat_preflight._resolve_live_aura_state()
        if live_state:
            live_state.cognition.conversation_energy = 0.0
            live_state.cognition.current_mode = 0  # CognitiveMode.REACTIVE
            live_state.response_modifiers["sys_pressure"] = "CRITICAL MEMORY LIMIT"
    if not snapshot.refuse_heavy_local_generation:
        return None

    reason = str(snapshot.reason or "foreground_memory_pressure_guard")
    logger.warning(
        "Unified memory admission refused foreground generation at %s: %s",
        phase,
        reason,
    )
    await _shed_generation_for_memory_pressure(reason)
    snapshot_payload = (
        snapshot.to_dict()
        if callable(getattr(snapshot, "to_dict", None))
        else {
            "critical": snapshot.critical,
            "refuse_heavy_local_generation": snapshot.refuse_heavy_local_generation,
            "reason": reason,
        }
    )
    return JSONResponse(
        {
            "response": (
                "I need to shed memory pressure before I can safely start the "
                "desktop model lane. I am blocking this turn instead of risking "
                "another system-level memory crash."
            ),
            "status": "memory_pressure_guard",
            "conversation_lane": _chat_preflight._collect_conversation_lane_status(),
            "memory_pressure": snapshot_payload,
            "response_confidence": "guarded",
        },
        status_code=503 if is_benchmark else 200,
    )


async def _preserve_large_user_paste(user_msg: str) -> None:
    """Keep large pasted text in live working memory for follow-up references."""
    content = str(user_msg or "").strip()
    if len(content) < 4000:
        return
    try:
        state = _chat_preflight._resolve_live_aura_state()
        cognition = getattr(state, "cognition", None) if state is not None else None
        working_memory = getattr(cognition, "working_memory", None)
        if not isinstance(working_memory, list):
            return
        if working_memory and str((working_memory[-1] or {}).get("content", "")) == content:
            return
        working_memory.append(
            {
                "role": "user",
                "content": content,
                "timestamp": time.time(),
                "origin": "api",
                "metadata": {
                    "type": "large_user_paste",
                    "source": "chat_api",
                    "preserve_for_followup": True,
                },
            }
        )
        if len(working_memory) > 80:
            del working_memory[: len(working_memory) - 80]
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Large paste preservation skipped: %s", exc)


def _resolve_exact_profile_user_id(request: Request) -> str:
    """Capture this request's authenticated relational principal."""
    try:
        return str(relational_principal_id_for_request(request) or "").strip()[:160]
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat.profile_identity", exc)
        logger.debug("Exact profile identity resolution failed: %s", exc)
        return ""


def _memory_log_outbox_is_ready() -> bool:
    persistence = ServiceContainer.get("persistence", default=None)
    return bool(
        callable(getattr(persistence, "claim_memory_log_batch", None))
        and callable(getattr(persistence, "settle_memory_log_item", None))
    )


async def _start_chat_turn_memory_log_when_ready() -> None:
    """Wait through normal service ordering, but never wait indefinitely."""

    deadline = time.monotonic() + _CHAT_TURN_MEMORY_LOG_STARTUP_TIMEOUT_S
    while time.monotonic() < deadline:
        if _memory_log_outbox_is_ready():
            if not _chat_preflight._schedule_chat_turn_memory_log(chat_origin="startup_recovery"):
                raise RuntimeError("chat_memory_log_startup_schedule_failed")
            return
        await asyncio.sleep(_CHAT_TURN_MEMORY_LOG_STARTUP_POLL_S)
    error = RuntimeError("persistence_memory_log_outbox_not_ready_before_deadline")
    record_degradation(
        "chat.memory_log_outbox_startup",
        error,
        action="durable outbox remains on disk and will be retried by the next chat write",
        enforce_failure_policy=False,
    )
    logger.error(
        "Durable chat memory outbox dependency was not ready within %.1fs; "
        "pending work remains on disk.",
        _CHAT_TURN_MEMORY_LOG_STARTUP_TIMEOUT_S,
    )


def start_chat_turn_memory_log_worker() -> bool:
    """Recover durable pending memory work when the API runtime starts."""
    if _memory_log_outbox_is_ready():
        return _chat_preflight._schedule_chat_turn_memory_log(chat_origin="startup_recovery")
    try:
        tracker = get_task_tracker()
        if _chat_preflight._active_task_count_by_name(
            tracker, _CHAT_TURN_MEMORY_LOG_STARTUP_TASK_NAME
        ):
            return True
        schedule = getattr(tracker, "bounded_track", None) or getattr(
            tracker,
            "create_task",
            None,
        )
        if not callable(schedule):
            raise RuntimeError("task_tracker_has_no_scheduler")
        waiter = _start_chat_turn_memory_log_when_ready()
        try:
            schedule(waiter, name=_CHAT_TURN_MEMORY_LOG_STARTUP_TASK_NAME)
        except _CHAT_RECOVERABLE_ERRORS:
            waiter.close()
            raise
        return True
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat.memory_log_outbox_startup", exc)
        logger.error("Durable chat memory outbox startup could not be scheduled: %s", exc)
        return False


#: A second, separate request following the thing to be remembered. Only an
#: explicit new ask counts — a wordy preamble around the memory request does
#: not, because that turn is still entirely about memory.


#: Words that carry no topic, so sharing them proves nothing about relevance.


def _memory_state_evidence_is_missing_from_reply(
    user_message: str,
    reply_text: str,
    memory_state_evidence: tuple[str, str] | None,
) -> bool:
    """Return True when canonical memory evidence was not honored visibly."""

    del user_message  # Reserved for future status-specific diagnostics.
    if not memory_state_evidence:
        return False

    memory_reply, memory_status = memory_state_evidence
    status = str(memory_status or "").strip()
    reply = str(reply_text or "").lower()
    if not reply:
        return True

    expected_content = _chat_memory_state._extract_session_memory_pin_request(
        str(memory_reply or "")
    )
    if not expected_content:
        match = re.search(r'"([^"]{1,240})"', str(memory_reply or ""))
        expected_content = match.group(1) if match else ""
    expected_content = str(expected_content or "").strip()

    if status in {
        "session_memory_pin",
        "session_memory_pin_transient",
        "session_memory_recall",
        "session_memory_context_recall",
    }:
        if not expected_content:
            return True
        return expected_content.lower() not in reply

    if status == "session_memory_miss":
        return not (
            "don't have" in reply
            or "do not have" in reply
            or "no pinned" in reply
            or "not pinned" in reply
        )

    if status in {"owner_identity_recall", "conversation_recall"}:
        return _conversation_recall_reply_is_inadequate(
            "",
            reply_text,
            str(memory_reply or ""),
        )

    return False


_MEMORY_STATE_COMPATIBLE_ASSESSMENT_REASONS = frozenset(
    {
        "off_topic_self_reflection_reply",
        "missing_requested_self_process_coverage",
        "too_thin_for_operational_status_turn",
        "too_thin_for_status_turn",
    }
)


def _canonical_memory_state_evidence_missing_from_reply(
    canonical_memory_state_evidence: str,
    reply_text: str,
) -> bool:
    """Return True when an inline canonical memory block was not reflected."""

    evidence = str(canonical_memory_state_evidence or "")
    reply = str(reply_text or "").lower()
    if not evidence.strip() or not reply.strip():
        return True

    status_match = re.search(r"^\s*status\s*=\s*([a-zA-Z0-9_:-]+)", evidence, re.MULTILINE)
    status = status_match.group(1).strip() if status_match else ""
    quoted = re.search(r'"([^"]{1,240})"', evidence)
    expected_content = quoted.group(1).strip() if quoted else ""

    if status in {
        "session_memory_pin",
        "session_memory_pin_transient",
        "session_memory_recall",
        "session_memory_context_recall",
    }:
        if not expected_content:
            return True
        return expected_content.lower() not in reply
    return False


def _memory_state_reply_satisfies_canonical_evidence(
    user_message: str,
    reply_text: str,
    *,
    memory_state_evidence: tuple[str, str] | None = None,
    canonical_memory_state_evidence: str = "",
) -> bool:
    """True only when visible prose honors the canonical memory/state evidence."""

    if memory_state_evidence:
        return not _memory_state_evidence_is_missing_from_reply(
            user_message,
            reply_text,
            memory_state_evidence,
        )
    if canonical_memory_state_evidence:
        return not _canonical_memory_state_evidence_missing_from_reply(
            canonical_memory_state_evidence,
            reply_text,
        )
    return False


def _reply_assessment_requires_repair_with_memory_evidence(
    assessment: Any,
    user_message: str,
    reply_text: str,
    *,
    memory_state_evidence: tuple[str, str] | None = None,
    canonical_memory_state_evidence: str = "",
) -> bool:
    """Keep hard failures, but do not reject honored memory/state replies as self-process misses."""

    if not _reply_assessment_requires_repair(assessment):
        return False
    reasons = set(getattr(assessment, "reasons", ()) or ())
    # A complete short answer is not a defect. "68" fails every thinness
    # heuristic there is and is still the whole correct answer to "what's
    # 17 times 4?" — live 2026-08-04 this gate turned it into "I couldn't
    # get to an answer I'd stand behind".
    try:
        from core.conversation.surface_disposition import (
            draft_is_servable,
            short_draft_answers_closed_question,
        )

        if (
            reasons
            and draft_is_servable(reasons)
            and short_draft_answers_closed_question(reply_text, user_message)
        ):
            return False
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation(
            "chat",
            exc,
            severity="warning",
            action="kept the standard repair path after the short-answer check failed",
        )
    if (
        reasons
        and reasons.issubset(_MEMORY_STATE_COMPATIBLE_ASSESSMENT_REASONS)
        and _memory_state_reply_satisfies_canonical_evidence(
            user_message,
            reply_text,
            memory_state_evidence=memory_state_evidence,
            canonical_memory_state_evidence=canonical_memory_state_evidence,
        )
    ):
        return False
    return True


def _canonical_memory_state_grounding_reply(
    user_message: str,
    canonical_memory_state_evidence: str,
    *,
    live_mind_context: dict[str, Any] | None = None,
) -> str | None:
    """Build a visible reply from canonical memory/state evidence after CE invocation.

    This is not a shortcut around cognition: the live desktop turn already
    invoked CognitiveEngine. This path prevents the speech surface from letting
    the generative organ erase canonical memory facts.
    """

    del user_message  # Kept for future status-specific phrasing.
    evidence = str(canonical_memory_state_evidence or "")
    if not evidence.strip():
        return None

    status_match = re.search(r"^\s*status\s*=\s*([a-zA-Z0-9_:-]+)", evidence, re.MULTILINE)
    status = status_match.group(1).strip() if status_match else ""
    quoted = re.search(r'"([^"]{1,240})"', evidence)
    expected_content = quoted.group(1).strip() if quoted else ""
    if not expected_content and status not in {"session_memory_miss"}:
        return None

    attention = ""
    if isinstance(live_mind_context, dict):
        voice = live_mind_context.get("voice")
        if isinstance(voice, dict):
            attention = str(
                voice.get("attention")
                or voice.get("attention_focus")
                or voice.get("dominant_action")
                or ""
            ).strip()
        if not attention:
            substrate = live_mind_context.get("substrate")
            if isinstance(substrate, dict):
                attention = str(
                    substrate.get("attention") or substrate.get("attention_focus") or ""
                ).strip()
    if attention:
        live_clause = f" Right now I am keeping attention on {attention[:120].rstrip('.')}."
    else:
        live_clause = " Right now I am keeping attention on this live desktop thread."

    if status in {"session_memory_pin", "session_memory_pin_transient"}:
        return f'I have pinned "{expected_content}" in this session.{live_clause}'
    if status in {"session_memory_recall", "session_memory_context_recall"}:
        return (
            f'You asked me to remember "{expected_content}". '
            "I am grounding that from canonical session memory rather than guessing from older chat context."
        )
    if status == "session_memory_miss":
        return "I do not have a pinned phrase from this session yet."
    return None


def _canonical_memory_state_evidence_from_tuple(
    memory_state_evidence: tuple[str, str] | None,
) -> str:
    """Convert the canonical memory/state tuple into the inline evidence block body."""

    if not memory_state_evidence:
        return ""
    memory_reply, memory_status = memory_state_evidence
    return (f"status={str(memory_status or '').strip()}\n{str(memory_reply or '').strip()}").strip()


def _extract_canonical_memory_state_evidence_block(effective_user_message: str) -> str:
    """Extract the canonical memory/state evidence block carried into CognitiveEngine."""

    text = str(effective_user_message or "")
    if "[CANONICAL MEMORY STATE EVIDENCE]" not in text:
        return ""
    match = re.search(
        r"\[CANONICAL MEMORY STATE EVIDENCE\]\s*(.*?)\s*\[END CANONICAL MEMORY STATE EVIDENCE\]",
        text,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if match:
        return match.group(1).strip()[:2400]
    return ""


_OWNER_DIRECT_ADDRESS_RE = re.compile(
    r"\b(?:hi|hey|hello|thanks|thank you|okay|ok|yes|no|sure|listen|look|"
    r"absolutely|definitely|right|agreed|got it|i'm here|i am here)\s*,?\s+"
    r"([A-Z][a-z]{2,24})\b",
    re.IGNORECASE,
)
_OWNER_IDENTITY_ASSERTION_RE = re.compile(
    r"\byou(?:'re| are)\s+([A-Z][a-z]{2,24})\b",
    re.IGNORECASE,
)
_OWNER_NAME_DRIFT_EXCLUSIONS = {
    "Aura",
    "User",
    "You",
    "Human",
    "Computer",
    "Mac",
    "Google",
    "Chrome",
    "ChatGPT",
    "Gemini",
}


def _owner_name_drift_candidates(reply_text: str) -> list[str]:
    candidates: list[str] = []
    for pattern in (_OWNER_DIRECT_ADDRESS_RE, _OWNER_IDENTITY_ASSERTION_RE):
        for match in pattern.finditer(str(reply_text or "")):
            name = str(match.group(1) or "").strip()
            if not name or name in _OWNER_NAME_DRIFT_EXCLUSIONS:
                continue
            if name not in candidates:
                candidates.append(name)
    return candidates


def _reply_has_owner_name_drift(
    user_message: str,
    reply_text: str,
    *,
    owner_session_restored: bool = False,
) -> bool:
    if not _chat_memory_state._owner_session_is_verified(
        owner_session_restored=owner_session_restored
    ):
        return False
    owner_name = _chat_memory_state._resolve_primary_operator_name().strip()
    if not owner_name or owner_name == "the verified owner":
        return False
    user = str(user_message or "")
    for candidate in _owner_name_drift_candidates(reply_text):
        if candidate.lower() == owner_name.lower():
            continue
        if re.search(rf"\b{re.escape(candidate)}\b", user):
            continue
        return True
    return False


def _repair_owner_name_drift_reply(reply_text: str) -> str:
    owner_name = _chat_memory_state._resolve_primary_operator_name().strip()
    if not owner_name or owner_name == "the verified owner":
        return str(reply_text or "")
    repaired = str(reply_text or "")
    for candidate in _owner_name_drift_candidates(repaired):
        if candidate.lower() == owner_name.lower():
            continue
        repaired = re.sub(rf"\b{re.escape(candidate)}\b", owner_name, repaired)
    return repaired


def _extract_repo_probe_request(user_message: str) -> dict[str, str] | None:
    text = str(user_message or "").strip()
    if not text:
        return None

    patterns = (
        (
            r"^(?:read|open|inspect)\s+([A-Za-z0-9_./~-]+\.[A-Za-z0-9]+)\s+and\s+tell me\s+the\s+first\s+non-comment\s+dependency\s+line[.?!]*$",
            "first_non_comment_dependency_line",
        ),
        (
            r"^(?:read|open|inspect)\s+([A-Za-z0-9_./~-]+\.[A-Za-z0-9]+)\s+and\s+tell me\s+the\s+first\s+non-comment\s+line[.?!]*$",
            "first_non_comment_line",
        ),
        (
            r"^(?:read|open|inspect)\s+([A-Za-z0-9_./~-]+\.[A-Za-z0-9]+)\s+and\s+tell me\s+how many\s+lines(?:\s+it\s+has)?[.?!]*$",
            "line_count",
        ),
    )
    for pattern, mode in patterns:
        match = re.match(pattern, text, flags=re.IGNORECASE)
        if match:
            return {"target": match.group(1), "mode": mode}
    return None


def _read_repo_probe_reply(user_message: str) -> dict[str, str] | None:
    request = _extract_repo_probe_request(user_message)
    if not request:
        return None

    try:
        from core.conversation.demo_support import _resolve_target_path

        target = str(request.get("target") or "").strip()
        mode = str(request.get("mode") or "").strip()
        path = _resolve_target_path(target)
        if not path:
            return {
                "reply": f"I reached for `{Path(target).name or target}` in my live workspace and couldn't find it cleanly.",
                "status": "repo_probe_missing",
            }

        size = path.stat().st_size
        if size > _REPO_PROBE_MAX_BYTES:
            return {
                "reply": (
                    f"`{path.name}` is larger than my bounded live-read budget "
                    f"({size} bytes > {_REPO_PROBE_MAX_BYTES} bytes), so I did not "
                    "pretend to inspect the whole file."
                ),
                "status": "repo_probe_too_large",
            }
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            source = handle.read(_REPO_PROBE_MAX_BYTES + 1)
        if len(source.encode("utf-8", errors="replace")) > _REPO_PROBE_MAX_BYTES:
            return {
                "reply": (
                    f"`{path.name}` exceeded my bounded live-read budget while I "
                    "was reading it, so I did not report a partial result as complete."
                ),
                "status": "repo_probe_too_large",
            }
        lines = source.splitlines()

        if mode == "first_non_comment_dependency_line":
            for line in lines:
                stripped = line.strip()
                if stripped and not stripped.startswith("#"):
                    reply = (
                        f"I read `{path.name}` directly. The first non-comment dependency line is "
                        f"`{stripped}`. That's coming from the live file, not from recall."
                    )
                    return {"reply": reply, "status": "repo_probe_dependency"}
            return {
                "reply": f"I read `{path.name}` directly, but I didn't find a non-comment dependency line in it.",
                "status": "repo_probe_empty",
            }

        if mode == "first_non_comment_line":
            for line in lines:
                stripped = line.strip()
                if stripped and not stripped.startswith("#"):
                    reply = (
                        f"I read `{path.name}` directly. The first non-comment line is "
                        f"`{stripped}`."
                    )
                    return {"reply": reply, "status": "repo_probe_line"}
            return {
                "reply": f"I read `{path.name}` directly, but every visible line is empty or commented out.",
                "status": "repo_probe_empty",
            }

        if mode == "line_count":
            reply = (
                f"I counted `{path.name}` directly in the live workspace. "
                f"It has {len(lines)} lines right now."
            )
            return {"reply": reply, "status": "repo_probe_line_count"}
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Repo probe read failed: %s", exc)

    return {
        "reply": "I reached for the file directly, but the live read didn't complete cleanly this time.",
        "status": "repo_probe_error",
    }


# ── Stale Response Detection ─────────────────────────────────
# Track the last N responses to detect when the cortex is stuck returning the
# same cached output. This prevents the "Dark Matter" loop where a stale
# identity prompt produces identical text on every turn.
@dataclasses.dataclass
class _ConversationQualityState:
    recent_responses: collections.deque[str] = dataclasses.field(
        default_factory=lambda: collections.deque(maxlen=12)
    )
    recent_response_pairs: collections.deque[tuple[str, str]] = dataclasses.field(
        default_factory=lambda: collections.deque(maxlen=12)
    )
    consecutive_degraded_count: int = 0
    lane_status_fingerprint: str = ""
    lane_status_repeat_count: int = 0
    conversation_resume_handle: str = ""
    conversation_resume_created_at: float = 0.0
    last_access_monotonic: float = dataclasses.field(default_factory=time.monotonic)


@dataclasses.dataclass(frozen=True)
class _ReplyQualitySnapshot:
    recent_user_messages: tuple[str, ...]
    is_stale: bool
    is_same_diff: bool
    is_off_topic: bool
    off_topic_reason: str
    semantic_glitch: bool
    semantic_glitch_reason: str
    reply_assessment: Any


_CHAT_REPLY_QUALITY_SNAPSHOTS: ContextVar[
    dict[tuple[str, str], _ReplyQualitySnapshot] | None
] = ContextVar("chat_reply_quality_snapshots", default=None)


_CONVERSATION_QUALITY_STATE_LIMIT = 256
_CONVERSATION_QUALITY_STATE_TTL_S = 6 * 60 * 60.0
_CONVERSATION_RESUME_TTL_S = 240.0
_DEFAULT_CONVERSATION_QUALITY_KEY = "default"
_conversation_quality_lock = checked_lock(
    "chat.conversation_quality_state",
    reentrant=True,
)
_conversation_quality_states: collections.OrderedDict[str, _ConversationQualityState] = (
    collections.OrderedDict([(_DEFAULT_CONVERSATION_QUALITY_KEY, _ConversationQualityState())])
)


def _conversation_quality_key(
    *,
    session_id: str = "",
    principal_id: str = "",
    principal_surface: str = "",
) -> str:
    session = " ".join(str(session_id or _CHAT_REQUEST_SESSION.get() or "").strip().split())[
        :_CHAT_SESSION_ID_MAX_CHARS
    ]
    principal = " ".join(str(principal_id or _CHAT_REQUEST_PRINCIPAL.get() or "").strip().split())[
        :160
    ]
    surface = str(principal_surface or _CHAT_REQUEST_SURFACE.get() or "").strip().casefold()[:32]
    if not session and not principal and not surface:
        return _DEFAULT_CONVERSATION_QUALITY_KEY
    identity = json.dumps(
        {"principal": principal, "session": session or "default", "surface": surface},
        ensure_ascii=True,
        separators=(",", ":"),
        sort_keys=True,
    )
    return hashlib.sha256(identity.encode("utf-8", errors="replace")).hexdigest()


def _conversation_quality_state_locked(
    *,
    session_id: str = "",
    principal_id: str = "",
    principal_surface: str = "",
) -> _ConversationQualityState:
    now = time.monotonic()
    key = _conversation_quality_key(
        session_id=session_id,
        principal_id=principal_id,
        principal_surface=principal_surface,
    )
    stale_keys = [
        candidate
        for candidate, state in _conversation_quality_states.items()
        if candidate != _DEFAULT_CONVERSATION_QUALITY_KEY
        and (now - state.last_access_monotonic) > _CONVERSATION_QUALITY_STATE_TTL_S
    ]
    for stale_key in stale_keys:
        _conversation_quality_states.pop(stale_key, None)
    state = _conversation_quality_states.get(key)
    if state is None:
        state = _ConversationQualityState()
        _conversation_quality_states[key] = state
    state.last_access_monotonic = now
    _conversation_quality_states.move_to_end(key)
    while len(_conversation_quality_states) > _CONVERSATION_QUALITY_STATE_LIMIT:
        oldest_key = next(iter(_conversation_quality_states))
        if oldest_key == _DEFAULT_CONVERSATION_QUALITY_KEY:
            _conversation_quality_states.move_to_end(oldest_key)
            continue
        _conversation_quality_states.popitem(last=False)
    return state


def _reset_conversation_quality_registry() -> None:
    """Clear transient per-conversation quality state without changing policy."""
    with _conversation_quality_lock:
        default = _conversation_quality_states.get(_DEFAULT_CONVERSATION_QUALITY_KEY)
        if default is None:
            default = _ConversationQualityState()
        default.recent_responses.clear()
        default.recent_response_pairs.clear()
        default.consecutive_degraded_count = 0
        default.lane_status_fingerprint = ""
        default.lane_status_repeat_count = 0
        default.conversation_resume_handle = ""
        default.conversation_resume_created_at = 0.0
        default.last_access_monotonic = time.monotonic()
        _conversation_quality_states.clear()
        _conversation_quality_states[_DEFAULT_CONVERSATION_QUALITY_KEY] = default


def _take_conversation_resume_handle(
    *,
    session_id: str = "",
    principal_id: str = "",
    principal_surface: str = "",
) -> str:
    """Consume this conversation's worker capability exactly once."""

    with _conversation_quality_lock:
        state = _conversation_quality_state_locked(
            session_id=session_id,
            principal_id=principal_id,
            principal_surface=principal_surface,
        )
        handle = str(state.conversation_resume_handle or "").strip().lower()
        age = time.monotonic() - float(state.conversation_resume_created_at or 0.0)
        state.conversation_resume_handle = ""
        state.conversation_resume_created_at = 0.0
    if age > _CONVERSATION_RESUME_TTL_S:
        return ""
    return handle if re.fullmatch(r"[0-9a-f]{32}", handle) else ""


def _store_conversation_resume_handle(
    turn_trace: dict[str, Any],
    delivered_text: str,
    *,
    session_id: str = "",
    principal_id: str = "",
    principal_surface: str = "",
) -> bool:
    """Retain exact KV only when it authored the exact bytes delivered."""

    receipt = turn_trace.get("live_mind_surface_control_receipt")
    receipt = dict(receipt) if isinstance(receipt, dict) else {}
    handle = str(receipt.get("conversation_resume_handle") or "").strip().lower()
    expected_hash = str(
        receipt.get("conversation_resume_output_sha256") or ""
    ).strip().lower()
    delivered_hash = hashlib.sha256(
        str(delivered_text or "").encode("utf-8", "replace")
    ).hexdigest()
    accepted = bool(
        re.fullmatch(r"[0-9a-f]{32}", handle)
        and re.fullmatch(r"[0-9a-f]{64}", expected_hash)
        and expected_hash == delivered_hash
        and turn_trace.get("cognitive_engine_reply_accepted") is True
        and turn_trace.get("bounded_contract_used") is not True
        and turn_trace.get("legacy_fallback_used") is not True
    )
    with _conversation_quality_lock:
        state = _conversation_quality_state_locked(
            session_id=session_id,
            principal_id=principal_id,
            principal_surface=principal_surface,
        )
        state.conversation_resume_handle = handle if accepted else ""
        state.conversation_resume_created_at = time.monotonic() if accepted else 0.0
    return accepted


def _increment_conversation_degradation_streak() -> int:
    with _conversation_quality_lock:
        state = _conversation_quality_state_locked()
        state.consecutive_degraded_count += 1
        return state.consecutive_degraded_count


def _set_conversation_degradation_streak(value: int) -> None:
    with _conversation_quality_lock:
        state = _conversation_quality_state_locked()
        state.consecutive_degraded_count = max(0, int(value))


def _conversation_degradation_streak() -> int:
    with _conversation_quality_lock:
        return _conversation_quality_state_locked().consecutive_degraded_count


