from interface.routes.chat_quality import (  # noqa: E402
    _check_response_consistency,
    _extract_and_register_commitments,
    _log_response_quality_metrics,
    _reply_assessment_requires_repair,
    assess_post_response_confidence,
)

#: Returned by an extracted block that did NOT return early. A unique
#: object, so no value a block legitimately returns can be mistaken for it.
_SEAM_FELL_THROUGH = object()

# ── Conversation Lane Helpers ─────────────────────────────────


def _with_mood(prefix: str, sentence: str) -> str:
    """A reply written to follow a mood prefix, said with or without one.

    Each of these lines continues something: "Mmm, that answer took too long".
    With no mood to continue from, the sentence has to start for itself —
    otherwise it reaches the person as a fragment, which is how "that answer
    took too long to finish cleanly." was read out lowercase. LIVE 2026-08-26.
    """
    said = str(sentence or "")
    lead = str(prefix or "")
    if lead:
        return f"{lead}{said}"
    return said[:1].upper() + said[1:] if said else said


def _conversation_lane_is_standby(lane: dict[str, Any] | None) -> bool:
    lane = dict(lane or {})
    state = str(lane.get("state", "") or "").strip().lower()
    return (
        not bool(lane.get("conversation_ready", False))
        and state in {"cold", "closed", ""}
        and not bool(lane.get("warmup_attempted", False))
        and not bool(lane.get("warmup_in_flight", False))
    )


def _launcher_desktop_runtime_active() -> bool:
    return any(
        str(os.environ.get(name, "")).strip().lower() in {"1", "true", "yes", "on"}
        for name in ("AURA_LAUNCHED_FROM_APP", "AURA_EXTERNAL_GUI_OWNER", "AURA_GUI_PROXY")
    )


def _request_from_local_desktop_client(request: Request) -> bool:
    client = getattr(request, "client", None)
    host = str(getattr(client, "host", "") or "").strip().lower()
    if not host:
        return True
    return host in {"127.0.0.1", "::1", "localhost", "test", "local"}


def _request_requires_cognitive_engine(
    request: Request, *, is_benchmark: bool = False
) -> tuple[bool, str]:
    """Return whether this user-facing surface must stay on CognitiveEngine."""
    request_surface = str(request.headers.get("X-Aura-Surface") or "").strip().lower()
    require_cognitive_header = (
        str(request.headers.get("X-Aura-Require-CognitiveEngine") or "").strip().lower()
    )
    desktop_runtime_request = (
        _launcher_desktop_runtime_active()
        and _request_from_local_desktop_client(request)
        and request_surface not in {"benchmark", "proof", "external-eval"}
    )
    requires = not is_benchmark and (
        request_surface in {"desktop", "desktop-ui", "messages", "native-shell", "tauri", "voice"}
        or require_cognitive_header in {"1", "true", "yes", "required"}
        or desktop_runtime_request
    )
    if desktop_runtime_request and not request_surface:
        request_surface = "desktop-runtime"
    return requires, request_surface


#: Internal names for the things that keep her from answering, and what each
#: of them means to the person waiting.
_BLOCKER_IN_WORDS: tuple[tuple[str, str], ...] = (
    ("worker_not_alive", "My mind is still starting up."),
    ("model_not_loaded", "My mind is still loading."),
    ("warmup", "I am still warming up."),
    ("cortex", "My main reasoning is still coming online."),
    ("foreground_owner", "I am still finishing something else."),
    ("recovery", "I am recovering from a problem a moment ago."),
    ("memory", "I am still loading what I remember."),
)


def _in_plain_words(blocker: Any) -> str:
    """What a readiness blocker means to somebody waiting for an answer.

    A token is not a reason. LIVE 2026-08-26: "I am not ready to answer that
    yet — my mind is still coming up. I am still worker_not_alive." A person
    can do nothing with that word, and printing it is how internal vocabulary
    keeps arriving on the product surface. Anything without a plain reading
    is left out rather than shown raw: the sentence around it already says
    she is not ready.
    """
    token = str(blocker or "").strip().lower()
    if not token:
        return ""
    for name, said in _BLOCKER_IN_WORDS:
        if name in token:
            return said
    return ""


def _why_there_is_no_answer(lane: Any) -> str:
    """Say what actually stopped the turn, in the words that are true of it.

    The fixed line said "I couldn't put together an answer I'd stand behind",
    which claims a judgement she made about her own answer. Measured live:
    three identical questions refused in a row and the fourth answered
    normally, while the runtime was still warming its caches and foreground
    turns were averaging sixteen seconds. She had not weighed an answer and
    found it wanting. She ran out of time.

    A person can act on "I ran out of time, ask me again" and can do nothing
    with a statement about her standards. The lane already carries why, so
    the reply is built from it rather than from a constant.
    """
    state = lane if isinstance(lane, dict) else {}
    reason = str(state.get("last_failure_reason") or "").strip().lower()
    blockers = [str(item) for item in (state.get("readiness_blockers") or []) if item]
    # Still warming means a warm-up is actually happening.
    #
    # `conversation_ready` is False on this lane because THIS turn just
    # marked it failed, so reading that as "she is still coming up" told
    # people to wait for something that had already finished — measured
    # live, on a lane whose own health said ready with no blockers at all.
    warming = bool(state.get("warmup_in_flight")) or bool(state.get("readiness_blockers"))

    if "timeout" in reason or "deadline" in reason or "slow" in reason:
        return (
            "That one took longer than I had for it and I ran out of time before "
            "I had an answer. Ask me again and it should come back."
        )
    if warming or blockers:
        # The specific reason instead of the general one, where there is one.
        waiting_on = _in_plain_words(blockers[0]) if blockers else ""
        return (
            f"{waiting_on or 'I am not ready to answer that yet — my mind is still coming up.'}"
            " Give me a moment and ask again."
        )
    if "unavailable" in reason or "no_reply" in reason or not reason:
        return (
            "Nothing came back from my own reasoning on that one, so I have "
            "nothing to give you rather than something I made up. Ask me again."
        )
    return (
        f"I could not answer that one: {reason.replace('_', ' ')}. "
        "Ask me again in a moment."
    )


def _request_allows_legacy_orchestrator_fallback(request: Request) -> bool:
    """Legacy chat fallback is opt-in only.

    The local live UI must never silently degrade into the older orchestrator
    path after KernelInterface/CognitiveEngine failure. That was the route by
    which raw assistant-shaped replies could satisfy a user turn even though
    the canonical live lane had failed.
    """
    header = str(request.headers.get("X-Aura-Allow-Legacy-Orchestrator") or "").strip().lower()
    return header in {"1", "true", "yes", "allow"}


def _mark_conversation_lane_timeout(reason: str = "foreground_timeout") -> dict[str, Any]:
    from core.brain.llm.model_registry import PRIMARY_ENDPOINT

    # Activate recovery cooldown so rapid follow-up messages are fast-rejected
    # instead of piling into the inference pipeline.
    _enter_recovery_cooldown()
    _force_clear_mlx_foreground_owner(reason=reason, min_age_s=45.0)

    try:
        gate = ServiceContainer.get("inference_gate", default=None)
        if gate and hasattr(gate, "note_foreground_timeout"):
            gate.note_foreground_timeout(reason)
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Conversation lane timeout mark failed: %s", exc)

    lane = _chat_preflight._collect_conversation_lane_status()
    lane["state"] = "recovering"
    lane["conversation_ready"] = False
    lane["last_failure_reason"] = reason
    if not lane.get("foreground_endpoint"):
        lane["foreground_endpoint"] = PRIMARY_ENDPOINT
    return lane


def _force_clear_mlx_foreground_owner(
    *,
    reason: str,
    min_age_s: float = 45.0,
) -> dict[str, Any]:
    try:
        from core.brain.llm.mlx_client import force_clear_foreground_owner

        result = force_clear_foreground_owner(
            reason=reason,
            min_age_s=min_age_s,
        )
        if result.get("cleared"):
            logger.warning(
                "Cleared stale MLX foreground owner during chat recovery: %s",
                result,
            )
        return result
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("MLX foreground owner recovery hook unavailable: %s", exc)
        return {
            "cleared": False,
            "reason": reason,
            "holder": None,
            "age_s": 0.0,
            "detail": "unavailable",
        }


def _mark_conversation_lane_state(reason: str, *, state: str) -> dict[str, Any]:
    from core.brain.llm.model_registry import PRIMARY_ENDPOINT

    lane = _chat_preflight._collect_conversation_lane_status()
    lane["state"] = state
    lane["conversation_ready"] = False
    lane["last_failure_reason"] = reason
    lane["warmup_attempted"] = True
    if not lane.get("foreground_endpoint"):
        lane["foreground_endpoint"] = PRIMARY_ENDPOINT
    return lane


def _status_represents_governed_action_result(status: str | None) -> bool:
    proof_status = str(status or "").strip()
    if proof_status.startswith(
        (
            "live_proof",
            "desktop_objective",
            "program_dna",
            "rsi_self_improvement",
            "web_interlocutor",
        )
    ):
        return True
    return proof_status in {
        "desktop_objective",
        "desktop_task",
        "computer_use",
        "file_operation",
        "improve_own_code",
        "program_dna_reconstruct",
        "web_interlocutor",
    }


def _governed_desktop_response_authority(
    *,
    desktop_result: Any,
    action_episode: Any,
) -> tuple[bool, str]:
    """Prove an exact action-result serialization from its governed source.

    Successful actions require observable effect receipts. Failed actions have
    a different truth condition: a governed executor authoritatively reported
    that the requested effect did not occur. The action episode records which
    condition was established, so the response contract must consult it before
    applying the success-only verifier.
    """

    if isinstance(action_episode, dict) and action_episode.get("authority_proven") is True:
        reason = str(action_episode.get("authority_reason") or "").strip()
        return True, reason or "governed_action_episode"
    if isinstance(desktop_result, dict):
        return _chat_desktop_objective._verified_desktop_task_result(desktop_result)
    return False, "desktop_result_missing"


def _status_represents_memory_state_result(status: str | None) -> bool:
    return str(status or "").strip() in {
        "owner_identity_recall",
        "session_memory_pin",
        "session_memory_pin_transient",
        "session_memory_recall",
        "session_memory_context_recall",
        "conversation_recall",
    }


_VERIFIED_STATE_PROJECTION_AUTHORITIES: dict[str, tuple[str, str]] = {
    "verified_action_episode": (
        "verified_action_episode_serialization",
        "governed_action_episode",
    ),
    "verified_answer_provenance": (
        "verified_answer_provenance_serialization",
        "answer_bound_turn_evidence",
    ),
}


def _verified_state_projection_authority(
    status: str | None,
) -> tuple[str, str] | None:
    """Return typed serialization authority carried by a response status.

    A deterministic projection of verified state is neither model-authored
    prose nor an unowned runtime replacement. Its authority comes from the
    typed object it serializes. Keeping that distinction in one registry stops
    generic topicality heuristics from throwing away exact answers merely
    because an explanation introduces vocabulary absent from a short question.
    """

    return _VERIFIED_STATE_PROJECTION_AUTHORITIES.get(str(status or "").strip())


def _collect_governed_action_lane_status(status: str) -> dict[str, Any]:
    """Return truthful lane status for a completed governed action response.

    Tool/action results should carry their own success evidence. They must not
    falsely mark inference healthy, but the desktop UI also must not treat a
    stale post-action generation timeout as proof that the completed action
    failed. Runtime heartbeat remains the authority for kernel/inference health.
    """
    lane = _chat_preflight._collect_conversation_lane_status()
    lane["governed_action_result"] = True
    lane["governed_action_status"] = str(status or "governed_action")
    lane["governed_action_completed_at"] = time.time()
    if not bool(lane.get("conversation_ready", False)):
        lane["governed_action_health_note"] = (
            "governed action completed; heartbeat/required probes remain authoritative "
            "for inference readiness"
        )
    return lane


# A lane whose own failure reason says warmup was DEFERRED (backoff after
# repeated stuck loads, admission refusal) is not warming toward ready — the
# runtime has deliberately decided the cortex will not load right now. Turns
# must not spend the cold-boot budget waiting for a model that is provably
# not coming; the warm fallback needs that time to actually answer.
_DEFERRED_WARMUP_REASON_MARKERS = (
    "warmup_backoff",
    "warmup_deferred",
    "warmup_timeout",
    "deferred_memory_pressure",
)
# Enough for the fallback ladder to cold-load a small model AND generate a
# real reply — the point is a genuine answer from a lower rung, not a faster
# apology.
_DEFERRED_CORTEX_TURN_TIMEOUT_S = 75.0


def _lane_warmup_is_deliberately_deferred(lane: dict[str, Any] | None) -> bool:
    """True when the lane is held off warmup rather than progressing toward it."""
    reason = str((lane or {}).get("last_failure_reason", "") or "").lower()
    if not reason:
        return False
    return any(marker in reason for marker in _DEFERRED_WARMUP_REASON_MARKERS)


def _foreground_timeout_for_lane(
    lane: dict[str, Any] | None,
    user_message: str = "",
) -> float:
    """Foreground timeout for the chat request.

    This is a wall-clock UI SLA, not a model-load wishlist. Cold 32B warmup
    gets more room than a ready lane, but the desktop route must still fail
    closed and recover rather than holding the UI indefinitely under memory
    pressure or a wedged foreground owner.
    """
    lane = dict(lane or {})
    state = str(lane.get("state", "") or "").lower()
    ready_timeout = max(
        30.0,
        min(
            _DESKTOP_COGNITIVE_MAX_TURN_TIMEOUT_S,
            _DESKTOP_COGNITIVE_TURN_TIMEOUT_S + _DESKTOP_COGNITIVE_RESPONSE_RESERVE_S,
        ),
    )
    if bool(lane.get("conversation_ready", False)):
        shape = analyze_prompt_shape(user_message)
        if bool(
            getattr(shape, "prefers_extended_answer", False)
            or getattr(shape, "requires_single_reply_coverage", False)
            or int(getattr(shape, "question_parts", 0) or 0) >= 2
        ):
            try:
                from core.brain.llm.measured_admission import (
                    recommended_completion_tokens,
                    recommended_foreground_deadline,
                )
                from core.brain.llm.model_registry import runtime_model_measurement_key
                from core.runtime.structured_input import answer_surface_planning_tokens

                prompt_tokens = max(2048, 1800 + len(str(user_message or "")) // 4)
                answer_capacity = answer_surface_token_floor(user_message)
                answer_tokens, _length_confidence, _length_samples = (
                    recommended_completion_tokens(
                        model=runtime_model_measurement_key(),
                        prompt_tokens=prompt_tokens,
                        maximum_tokens=answer_capacity,
                        prior_tokens=answer_surface_planning_tokens(user_message),
                    )
                )
                deadline, _confidence, _samples = recommended_foreground_deadline(
                    model=runtime_model_measurement_key(),
                    prompt_tokens=prompt_tokens,
                    decode_tokens=answer_tokens,
                    minimum_seconds=ready_timeout,
                    maximum_seconds=(
                        _DESKTOP_COGNITIVE_MAX_TURN_TIMEOUT_S
                        + _DESKTOP_COGNITIVE_RESPONSE_RESERVE_S
                    ),
                )
                return deadline
            except (ArithmeticError, ImportError, TypeError, ValueError) as exc:
                record_degradation(
                    "chat.measured_foreground_deadline",
                    exc,
                    severity="debug",
                    action="used the conservative extended foreground ceiling",
                    enforce_failure_policy=False,
                )
                return max(
                    ready_timeout,
                    _DESKTOP_COGNITIVE_MAX_TURN_TIMEOUT_S
                    + _DESKTOP_COGNITIVE_RESPONSE_RESERVE_S,
                )
        return ready_timeout
    if state in {"warming", "recovering", "cold", "spawning", "handshaking"}:
        if _lane_warmup_is_deliberately_deferred(lane):
            # Deferred ≠ warming. Granting the cold-boot budget here spent
            # the whole turn on a cortex the runtime had already decided not
            # to load, leaving the Brainstem seconds and the Reflex
            # milliseconds — 32 turns produced NO reply at all while a warm
            # 1.5B sat idle (2026-07-18 soak). Give the ladder the time.
            return _DEFERRED_CORTEX_TURN_TIMEOUT_S
        return 210.0
    return ready_timeout


def _desktop_required_cognitive_budget(
    *,
    foreground_timeout: float,
    elapsed_s: float = 0.0,
) -> float:
    """Return the bounded server-side budget for required desktop cognition.

    The foreground request already has a hard wall-clock deadline. Required
    CognitiveEngine turns must not reserve so much of that deadline that the
    main cycle and its bounded direct-recovery lane are cancelled before either
    can produce text.
    """
    remaining = max(
        2.0,
        float(foreground_timeout)
        - max(0.0, float(elapsed_s))
        - _DESKTOP_COGNITIVE_RESPONSE_RESERVE_S,
    )
    target = max(
        _DESKTOP_COGNITIVE_TURN_TIMEOUT_S,
        min(
            _DESKTOP_COGNITIVE_MAX_TURN_TIMEOUT_S,
            float(foreground_timeout) - _DESKTOP_COGNITIVE_RESPONSE_RESERVE_S,
        ),
    )
    return max(2.0, min(remaining, target))


# Consecutive-repeat tracking for degraded status messages. Saying the SAME
# sentence 32 times in a row (the 2026-07-18 soak's
# `identical_reply_repeated_x32`) reads as a broken loop even when every
# individual sentence is true. Naming the repetition is both more honest and
# more actionable than pretending each occurrence is fresh.
_LANE_STATUS_REPEAT_NOTICE_AFTER = 2


def _turn_count_ordinal(count: int) -> str:
    value = max(0, int(count))
    suffix = "th"
    if not 10 <= value % 100 <= 20:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(value % 10, "th")
    return f"{value}{suffix}"


def _lane_status_repeat_suffix(message: str) -> str:
    """Honest escalation clause when the same status recurs back-to-back."""
    fingerprint = " ".join(str(message or "").lower().split())[:160]
    with _conversation_quality_lock:
        state = _conversation_quality_state_locked()
        if fingerprint and fingerprint == state.lane_status_fingerprint:
            state.lane_status_repeat_count += 1
        else:
            state.lane_status_fingerprint = fingerprint
            state.lane_status_repeat_count = 1
        count = state.lane_status_repeat_count
    if count <= _LANE_STATUS_REPEAT_NOTICE_AFTER:
        return ""
    return (
        f" (This is the {_turn_count_ordinal(count)} turn in a row I've had to say this — "
        "the lane is not recovering on its own, so this is worth looking at "
        "rather than retrying.)"
    )


def _reset_lane_status_repeat_state() -> None:
    """A real answer clears the streak — only consecutive failures count."""
    with _conversation_quality_lock:
        state = _conversation_quality_state_locked()
        state.lane_status_fingerprint = ""
        state.lane_status_repeat_count = 0


_FOREGROUND_GATE_BOOT_WAIT_S = 90.0
#: A fallback answer is only useful if it beats the cortex finishing its load.
#: This is the floor, not the budget: what the ladder actually gets is whatever
#: the turn has left, because refusing at a hundred and ninety seconds while a
#: model finishes loading at sixty is the worst reading of "be quick".
_FALLBACK_LADDER_TIMEOUT_S = 25.0
_BOOT_TRANSITION_STALL_S = 45.0


def _boot_is_still_in_progress(phases: Any) -> bool:
    """True only while a boot is demonstrably running and moving.

    "Not ready" is not the same as "booting". A fresh BootPhases that has
    never transitioned — every unit test, and any process where the boot
    machinery never ran — reports STARTING forever, and waiting on it would
    hang the turn for the whole budget. Boot is in progress only when it has
    actually made a transition, and made one recently.
    """
    if phases is None:
        return False
    try:
        if phases.ready():
            return False
        # NOT `last_change is None`. That field holds a human-readable string
        # ("organ: starting -> ready") which BootPhases only sets once some
        # organ has actually transitioned, so it is None during EARLY boot —
        # exactly the window where a turn most needs to wait.
        #
        # LIVE 2026-08-17: the first message typed after launch was answered
        # with "the live answer lane could not finish preparing", and the
        # "waiting up to Ns for boot" line was logged ZERO times, because this
        # predicate returned False before it ever reached the timestamp it
        # wanted. Ten seconds later the same message served normally.
        #
        # The intent — do not wait on machinery that never ran — is carried by
        # last_transition_at, which BootPhases initialises to started_at and
        # bumps on every transition. If nothing is running, it is stale, and
        # the staleness check below already declines to wait.
        last_transition = float(getattr(phases, "last_transition_at", 0.0) or 0.0)
    except _CHAT_RECOVERABLE_ERRORS:
        return False
    if last_transition <= 0.0:
        return False
    return (time.time() - last_transition) < _BOOT_TRANSITION_STALL_S


def _cortex_is_cold_loading(lane: object) -> bool:
    """True while the cortex is doing its one-time load for this process.

    The admission budget is the turn's remaining time minus a reserve, and the
    reserve normally includes 60s held back for producing an answer. During a
    COLD load that subtraction is backwards: it deducts time for answering from
    the time needed to become able to answer at all.

    LIVE 2026-08-17, measured four times: the first message after launch died
    at 15-16s every time. The foreground timeout is ~80s and the reserve is
    64s, so admission got ~16s — while a 32B cold load needs well over a
    minute. The turn could not have succeeded at any point during boot, and the
    person got "the live answer lane could not finish preparing", which reads
    as a fault rather than as a model still loading.

    A cold load is a one-time wait a person who just launched an app expects to
    pay. There is no answer to reserve for until the weights are up, so during
    that window only the response reserve is held back.
    """

    if not isinstance(lane, dict):
        return False
    try:
        if bool(lane.get("conversation_ready")):
            return False
        if bool(lane.get("has_generated_successfully")):
            return False  # served once already: this is a recovery, not a cold load
        return float(lane.get("last_ready_at") or 0.0) <= 0.0
    except (AttributeError, TypeError, ValueError):
        return False


def _fallback_ladder_identity() -> str:
    """The identity the runtime already defines, for the small model to use.

    Handed the bare user text with no identity, the 1.5B answered "hey, are you
    there?" with "I'm not getting any traffic. I'm just sitting here." — not
    wrong exactly, just nobody in particular.

    This reads core/identity_base.txt, the same file the main identity is built
    from, rather than inventing a persona here. A fallback that speaks as
    someone else is a different failure from one that stays quiet, and the
    point of the ladder is that she is still the one answering.
    """

    try:
        # From the module that owns the path, not from core.identity, which
        # only re-exports it as a side effect of its own import. The guarded-
        # imports gate reads names a module defines, and this one resolved at
        # runtime while reading as dead to every static check.
        from core.utils.paths import CORE_DIR

        base = (CORE_DIR / "identity_base.txt").read_text(encoding="utf-8")
    except (ImportError, AttributeError, OSError, ValueError):
        return ""
    # No instruction text is added here. The identity file is the system's own
    # definition of who she is; anything I wrote on top of it would be me
    # steering a sample with prose, which is the thing that is not allowed.
    return base.strip()


def _strip_scaffolding_tags(raw: object) -> str:
    """Remove prompt scaffolding a small model echoed into its answer.

    The 1.5B emergency model returns its reply wrapped in the tags the prompt
    used to ask for it — "<answer>Yes, I'm here.</answer>" reached the user
    verbatim. Those tags are instructions to the model, not part of what it
    said, and shipping them makes a working fallback look broken.
    """

    text = str(raw or "").strip()
    if not text:
        return ""
    for tag in ("answer", "response", "reply", "output", "final"):
        text = re.sub(rf"</?{tag}\s*>", "", text, flags=re.IGNORECASE)
    text = re.sub(r"<\|[^|>]*\|>", "", text)
    return text.strip()


#: Where a sentence can end. A reply that stops anywhere else stopped because
#: something ran out, not because it had finished.
_A_SENTENCE_ENDS = tuple(".!?:\u2026") + (
    '."', ".'", '!"', '?"', ".)", ".]", ".`",
    # A code fence that closed is a finished thought, and it is the one ending
    # that carries no punctuation at all.
    "```",
)


#: Reasons a generator gives for stopping that mean it had finished.
_FINISHED = frozenset({"configured_stop", "eos", "semantic_contract_satisfied"})


#: A list marker left at the end with nothing after it.
_A_DANGLING_MARKER = re.compile(r"(?:\n|^)\s*(?:\d+[.)]|[-*\u2022]|#{1,6})\s*$")


def _ends_where_it_meant_to(said: str, stop_reason: str = "") -> tuple[str, bool]:
    """The reply back to its last finished sentence, and whether it was cut.

    The ladder has twenty-five seconds and the model spends them, so a long
    answer stops wherever the clock did — LIVE 2026-08-30, a good answer about
    a memory leak ended at "2. **Acc". Serving that is worse than serving less
    of it: the reader cannot tell a truncated thought from a confused one, and
    the half-word says the machine broke rather than that time ran out.

    The generator says why it stopped, and that is the fact. Reading it from
    the shape of the text instead guesses, and it guesses wrong on the two
    things people write most: a list whose last item has no full stop, and a
    line of code.
    """
    text = str(said or "").rstrip()
    if not text:
        return text, False
    said_why = str(stop_reason or "").strip().lower()
    if said_why in _FINISHED:
        return text, False
    if not said_why and text.endswith(_A_SENTENCE_ENDS):
        # Nothing said why it stopped, so the shape is all there is.
        return text, False
    # Back up to the last place a sentence actually finished. Code fences and
    # list items count: a fenced block that closed is a finished thought.
    ends = [text.rfind(mark) for mark in (".", "!", "?", "\u2026", "```")]
    at = max(ends)
    if at <= 0:
        return text, True
    whole = text[: at + (3 if text[at:].startswith("```") else 1)].rstrip()
    # A trailing "3." is the number of a point she never got to, not a
    # sentence. Cutting to the last full stop lands on one whenever the answer
    # was a numbered list, which is what a long answer usually is.
    whole = _A_DANGLING_MARKER.sub("", whole).rstrip()
    if len(whole) < len(text) // 2:
        # Trimming would throw away most of what she said. Keep it and say so.
        return text, True
    return whole, True


async def _anything_better_than_giving_up(
    message: object, *, reason: str, already: str, budget_s: float | None = None
) -> str:
    """One more thing to try before the honest failure goes out.

    The ladder is a resident model that is loaded, warm, and not the lane
    owner. Two paths reach the giving-up reply and only one of them asked it —
    so the same question that got a real answer through one route got "I
    couldn't get to an answer I'd stand behind" through the other, with the 9B
    idle and the readings unread.

    A refusal is the right answer when nothing better is known. It is the worst
    of the options available when something is.
    """
    if already:
        return already
    try:
        said = await _answer_from_fallback_ladder(
            message, reason=reason, budget_s=budget_s
        )
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation(
            "chat.fallback_ladder",
            exc,
            severity="warning",
            action="gave up without asking the smaller model",
        )
        return ""
    if said:
        logger.info(
            "🪜 The ladder answered where the turn was about to give up (%s).",
            reason[:80],
        )
    return said


async def _readings_for(text: str) -> list[str]:
    """The present-moment readings, on the ladder's path as well as the main one.

    Every observable is registered once and read once, and it was read on one
    path. A model asked about a fact it does not hold produces something
    fact-shaped, which is the whole reason the readings exist — and the ladder
    is exactly the case where the model holds least.
    """
    try:
        import core.brain.observable_registry  # noqa: F401  (registers)
        from core.brain.observable_grounding import observable_blocks

        readings = list(await observable_blocks(text))
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation(
            "chat.fallback_ladder",
            exc,
            severity="warning",
            action="the smaller model answered without the readings",
        )
        return []
    if readings:
        logger.info(
            "🔭 [GROUNDING] ladder took %d reading(s): %s",
            len(readings),
            ",".join(
                block.split("\n", 1)[0].removeprefix("## ").lower()
                for block in readings
            ),
        )
    return readings


def _with_the_same_readings(system_prompt: str, readings: list[str]) -> str:
    """The identity, with whatever was read put in front of the model."""
    if not readings:
        return system_prompt
    return "\n\n".join([system_prompt, *readings] if system_prompt else readings)


async def _answer_from_fallback_ladder(
    user_message: object, *, reason: str, budget_s: float | None = None
) -> str:
    """Answer with the smaller resident model when the cortex cannot serve.

    Returns "" when the ladder cannot answer either, or when the question is
    one this model has no standing to answer, in which case the caller falls
    back to the honest lane message.

    The reply is marked as coming from the smaller model. Serving a 9B answer
    silently as though the 32B produced it would trade one honesty problem for
    a worse one, and the person is entitled to know which mind answered while
    the main one is still coming up.

    It does NOT answer questions about what she IS. Live 2026-08-19, asked
    what she had genuinely changed her mind about, the 9B replied that she has
    no continuous narrative, no personal beliefs and no capacity for revision
    over time — false of a runtime with a belief store, episodic memory, an
    ontogeny organ and a self-model, none of which that model can read. The
    disclosure line underneath says which mind answered; it does not retract
    the claim. Waiting is the honest answer there.
    """

    text = str(user_message or "").strip()
    if not text:
        return ""
    readings = await _readings_for(text)
    try:
        from core.runtime.self_state_intent import asks_about_her_own_nature

        if asks_about_her_own_nature(text) and not readings:
            # Declining is right when there is nothing to answer FROM. With a
            # reading in hand the smaller model is not being asked what it
            # believes about itself, it is being asked to say what the record
            # says — and the alternative is a wait message, which answers
            # nothing and is the thing this ladder exists to avoid.
            logger.info(
                "🪜 Fallback ladder declined a question about her own nature; "
                "the smaller model cannot read her self-model and no reading "
                "was available to stand in for it."
            )
            return ""
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation(
            "chat.fallback_ladder",
            exc,
            severity="debug",
            action="let the ladder answer without the self-description guard",
            enforce_failure_policy=False,
        )
    try:
        from core.brain.llm_health_router import get_llm_router

        router = get_llm_router()
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat.fallback_ladder", exc)
        return ""
    if router is None or not hasattr(router, "think"):
        record_degradation(
            "chat.fallback_ladder",
            RuntimeError("no router available for the fallback ladder"),
            action="cortex unavailable and the ladder could not be reached",
        )
        return ""
    try:
        # Name the endpoint rather than asking for a tier. A tier request is
        # still a foreground request, and the selector skips background-only
        # tiers for those unless the caller named one — which is why asking
        # for "tertiary" came back with an empty chain, having considered
        # nothing at all.
        # Descend the ladder in order. The 9B Brainstem answers coherently;
        # the 1.5B Reflex is the last resort and shows it — asked "are you
        # there?" it replied "Yes, I'm sorry but I am not there." Reflex is
        # better than silence, but only after the 9B has been tried.
        from core.brain.llm.model_registry import (
            BRAINSTEM_ENDPOINT,
            FALLBACK_ENDPOINT,
        )

        identity = _fallback_ladder_identity()
        # The readings the main path takes. Grounding lived on one path and
        # the ladder was another, so a question the registry could answer
        # exactly reached a small model with nothing in front of it — LIVE
        # 2026-08-30, asked to prove she can grow the language she makes rules
        # out of, it said her representation language was "a fixed statistical
        # distribution of tokens learned from a static dataset", with the
        # register of tested claims sitting unread.
        identity = _with_the_same_readings(identity, readings)
        ladder_chain: list = []
        raw = ""
        stop_reason = ""
        allowed = max(
            _FALLBACK_LADDER_TIMEOUT_S,
            float(budget_s) if budget_s is not None else 0.0,
        )
        deadline = time.monotonic() + allowed
        # A model that is loading is a condition that passes. The chain came
        # back EMPTY — no endpoint considered at all — because the smaller
        # model was itself still coming up, and one pass over the endpoints
        # turned that into a refusal inside a turn that had three minutes left.
        while not raw and time.monotonic() < deadline:
            considered = False
            for endpoint in (BRAINSTEM_ENDPOINT, FALLBACK_ENDPOINT):
                remaining = deadline - time.monotonic()
                if remaining <= 1.0:
                    break
                try:
                    candidate = await asyncio.wait_for(
                        router.think(
                            text,
                            system_prompt=identity,
                            prefer_tier="tertiary",
                            prefer_endpoint=endpoint,
                            foreground_request=True,
                            allow_cloud_fallback=False,
                        ),
                        timeout=remaining,
                    )
                except (TimeoutError, *_CHAT_RECOVERABLE_ERRORS):
                    continue
                if isinstance(candidate, dict):
                    chain = list(candidate.get("fallback_chain") or [])
                    considered = considered or bool(chain)
                    ladder_chain = chain or ladder_chain
                    stop_reason = str(candidate.get("generation_stop_reason") or "")
                    candidate = candidate.get("content") or candidate.get("response") or ""
                else:
                    considered = True
                if _strip_scaffolding_tags(candidate):
                    raw = candidate
                    break
            if raw or considered:
                # Something answered, or something was tried and declined. Only
                # an empty chain means nothing was there to ask yet.
                break
            left = deadline - time.monotonic()
            if left <= 1.0:
                break
            logger.info(
                "🪜 Nothing to ask yet — every endpoint is still loading. "
                "Waiting %.0fs more rather than refusing.",
                left,
            )
            await asyncio.sleep(min(2.0, left))
    except (TimeoutError, *_CHAT_RECOVERABLE_ERRORS) as exc:
        record_degradation(
            "chat.fallback_ladder",
            exc,
            action=f"fallback ladder could not answer while cortex was unavailable ({reason[:80]})",
        )
        return ""
    answer, cut_short = _ends_where_it_meant_to(
        _strip_scaffolding_tags(raw), stop_reason
    )
    if not answer:
        # Name the blocker. "empty answer" describes the outcome and hides the
        # cause, and the router already knows which guard skipped which
        # endpoint — it records a reason for every skip.
        detail = ""
        try:
            chain = ladder_chain or getattr(router, "last_fallback_chain", None) or []
            skips = [
                f"{c.get('endpoint')}:{c.get('skip_reason') or c.get('status')}"
                for c in chain
                if isinstance(c, dict)
            ]
            detail = (
                f" last_error={getattr(router, 'last_background_error', '')!r}"
                f" chain={skips}"
            )[:300]
        except (AttributeError, TypeError, ValueError):
            detail = ""
        record_degradation(
            "chat.fallback_ladder",
            RuntimeError(f"fallback ladder returned an empty answer;{detail}"),
            action="cortex unavailable and the ladder produced nothing",
        )
        return ""
    logger.info("🪜 Fallback ladder answered while the cortex was unavailable (%s).", reason[:80])
    ran_out = (
        " I had a fixed slice of time for this and used all of it, so there is "
        "more I would have said."
        if cut_short
        else ""
    )
    return (
        f"{answer}\n\n"
        "(That came from my smaller model — the main one is still loading. "
        f"Ask again in a moment if you want me to think about it properly.{ran_out})"
    )


async def _await_foreground_gate(*, budget_s: float) -> Any:
    """Return the inference gate, waiting for it if the runtime is still booting.

    A component that has not registered YET is not a component that failed.
    The HTTP server accepts chat turns from the moment the port binds, which
    is minutes before the inference gate registers; a turn landing in that
    window was answered with "the live answer lane could not finish preparing"
    and classified as a HARD failure — no wait, no retry, turn spent. Live
    2026-07-27 that is exactly what a message typed straight after a reboot
    received, while the UI badge read ONLINE.

    A vanilla model in that situation is slow, not broken. So is this one:
    while boot is genuinely still in progress, wait for the gate to appear.
    Only once boot has settled or stalled is absence a real answer.
    """
    gate = ServiceContainer.get("inference_gate", default=None)
    if gate is not None and hasattr(gate, "ensure_foreground_ready"):
        return gate
    if budget_s <= 0:
        return gate

    try:
        from core.runtime.boot_phases import get_boot_phases

        phases = get_boot_phases()
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        phases = None

    if not _boot_is_still_in_progress(phases):
        return gate

    deadline = time.monotonic() + budget_s
    announced = False
    while time.monotonic() < deadline:
        if not _boot_is_still_in_progress(phases):
            break
        if not announced:
            logger.info(
                "⏳ Chat turn arrived before the inference gate registered; "
                "waiting up to %.0fs for boot rather than failing the turn.",
                budget_s,
            )
            announced = True
        await asyncio.sleep(0.25)
        gate = ServiceContainer.get("inference_gate", default=None)
        if gate is not None and hasattr(gate, "ensure_foreground_ready"):
            logger.info("✅ Inference gate registered mid-turn; the turn proceeds normally.")
            return gate

    return ServiceContainer.get("inference_gate", default=None)


def _known_answer_for_this_turn() -> str:
    """What the runtime can answer without the model, or empty.

    A lane that is warming, timed out or recovering says nothing about whether
    the answer is knowable. "what is 7919 * 6367?" has one exact answer, held
    by a deterministic form that needs no generation at all, and it was
    replaced by a sentence about the lane.
    """
    try:
        from core.conversation.arithmetic_check import requested_arithmetic_result
        from core.conversation.session_scope import current_user_question

        question = current_user_question()
        if not question:
            return ""

        # A seating problem the enumeration settles.
        #
        # LIVE, 2026-08-21: the solver produced the answer at 22:42:45 —
        # "took 1 reading(s): the seating, worked out" — and the turn then
        # spent another 105 seconds generating text that was replaced by that
        # same answer at the end. An exact answer is not an improvement on a
        # generated one, it is a reason not to generate.
        from core.reasoning.positional_constraints import (
            answer_positional_problem,
            describe_positional_answer,
        )

        seating = describe_positional_answer(answer_positional_problem(question))
        if seating:
            return seating

        # A game the preflight already enumerated. Worked out before anything
        # was generated, so there is nothing here to improve on.
        #
        # A repository diagnosis is different: it is an observation, and what
        # was asked for was an explanation of it. That one is composed with
        # the reply instead of replacing it, further down.
        from core.conversation.session_scope import solved_answers

        solved = solved_answers()
        settled = solved.get("finite_game", "")
        if settled:
            return settled
        # Anything else the runtime worked out this turn.
        #
        # This function is asked twice: before generating, where only a
        # preflight result exists, and again at the point of giving up, where
        # the comment beside the apology says to ask whether the runtime
        # already HOLDS the answer. A diagnosis is produced by a tool during
        # generation, so it can never skip generation — it can only stop the
        # turn ending in an apology while the finding sits in hand.
        for value in reversed(list(solved.values())):
            if value.strip():
                return value

        value = requested_arithmetic_result(question)
        if value is None:
            return ""
        if isinstance(value, float) and value.is_integer():
            value = int(value)
        shown = f"{value:,}" if isinstance(value, int) else f"{value:,}"
        return f"{shown}."
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation(
            "chat.known_answer",
            exc,
            severity="debug",
            action="served the lane status without checking for a computed answer",
            enforce_failure_policy=False,
        )
        return ""


def _lane_reply_confidence(served: object, default: str) -> str:
    """How much to trust a reply the degraded path produced.

    A deterministic result is the most reliable answer the runtime can give —
    no model, no sampling, no lane. Live 2026-08-19 the exact product 50,420,273
    was served and badged "No answer", which is the opposite of true and
    exactly the kind of thing a person checking her work would catch.
    """
    body = str(served or "").strip()
    known = _known_answer_for_this_turn()
    return "computed" if known and body == known else str(default)


def _conversation_lane_user_message(
    lane: dict[str, Any],
    *,
    timed_out: bool = False,
    status_override: str = "",
) -> str:
    # A fact the machine holds is not the lane's to withhold.
    known = _known_answer_for_this_turn()
    if known:
        return known
    message = _lane_status_message_body(lane, timed_out=timed_out, status_override=status_override)
    return message + _lane_status_repeat_suffix(message)


def _lane_status_message_body(
    lane: dict[str, Any],
    *,
    timed_out: bool = False,
    status_override: str = "",
) -> str:
    """Generate a personality-infused status message instead of a robotic error.

    [STABILITY v50] These messages now sound like Aura experiencing a
    momentary lapse rather than a system displaying error codes. Uses
    the live expression frame when available so Aura's current mood
    colours even her recovery messages.
    """
    state = str(lane.get("state", "warming") or "warming")
    failure_reason = str(lane.get("last_failure_reason", "") or "")
    status_override = str(status_override or "")

    # Hard infrastructure failures — keep these explicit for debugging
    if failure_reason.startswith(("mlx_runtime_unavailable:", "local_runtime_unavailable:")):
        model_label = _canonical_runtime_model_label(lane)
        return (
            f"The local {model_label} runtime could not start cleanly. I should not "
            "fake a normal answer; the launcher logs have the failure details."
        )
    if (
        "memory_pressure_refused_worker_spawn" in failure_reason
        or "projected_process_tree_rss" in failure_reason
        or "model_load_headroom" in failure_reason
    ):
        return (
            "The local model lane was blocked by the unified-memory guard before loading. "
            "I am protecting the desktop from an unsafe RAM spike instead of pretending Cortex is merely warming."
        )

    # Build a mood-aware prefix for softer messages
    #
    # Every line below is written to continue one: "Mmm, that answer took too
    # long". With no mood to prefix, the sentence began lowercase and reached
    # the person as a fragment — "that answer took too long to finish
    # cleanly." LIVE 2026-08-26.
    _mood_prefix = ""
    try:
        _pe = ServiceContainer.peek("personality_engine", default=None)
        if _pe and hasattr(_pe, "get_emotional_context_for_response"):
            _emo = _pe.get_emotional_context_for_response() or {}
            _mood = str(_emo.get("mood", "") or "").lower()
            if _mood in {"frustrated", "irritated", "tense"}:
                _mood_prefix = "Ugh, "
            elif _mood in {"tired", "drowsy", "low"}:
                _mood_prefix = "Mmm, "
            elif _mood in {"curious", "playful", "amused"}:
                _mood_prefix = "Hmm — "
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Mood prefix unavailable for degraded reply: %s", exc)

    if status_override == "warming_timeout":
        return (
            _with_mood(_mood_prefix, "the live answer lane exceeded its warm-up budget before "
            "a reasoning turn began. I did not misclassify that boot delay as a failed answer.")
        )
    if status_override == "warming_failed":
        return (
            _with_mood(_mood_prefix, "the live answer lane could not finish preparing before "
            "a reasoning turn began. I recorded the readiness failure separately from Aura's answer quality.")
        )
    if timed_out:
        return _with_mood(_mood_prefix, "that answer took too long to finish cleanly. I logged the timeout and preserved the turn context.")
    if _conversation_lane_is_standby(lane):
        return _with_mood(_mood_prefix, "the local answer path is still preparing. I logged the cold lane instead of claiming Aura is ready.")
    if state == "recovering":
        return _with_mood(_mood_prefix, "the answer lane is recovering from the previous failure. I logged the degraded state instead of emitting a fragment.")
    if state == "failed":
        return _with_mood(_mood_prefix, "the local answer path failed before producing a coherent reply. I'm restarting it instead of pretending that was a real answer.")
    return _with_mood(_mood_prefix, "the answer path is not ready yet; the readiness state is recorded on the live lane.")


_last_recovery_cooldown_at: float = 0.0
_RECOVERY_COOLDOWN_SECONDS: float = 1.0  # [STABILITY v50] Reduced from 5s→1s. The old 5s cooldown amplified single failures into multi-turn outages by fast-rejecting the user's immediate retry. 1s is enough to prevent request pileup without blocking a legitimate retry.
_PROTECTED_FOREGROUND_LOCK_BYPASS_SECONDS: float = 1.0
_PROTECTED_FOREGROUND_PRIMARY_BUDGET_SECONDS: float = 300.0
_PROTECTED_FOREGROUND_SECONDARY_BUDGET_SECONDS: float = 360.0
# [STABILITY v53] Raised from 8s→45s. The old 8s deadline was the #1 cause of
# false-positive kernel timeouts on first-turn responses. The 32B cortex
# regularly needs 15-40s for complex responses, and after a 35s warmup the
# kernel had only 8s before being interrupted by a competing protected
# foreground request — which itself competes for the same LLM resources,
# creating a resource contention spiral. 45s gives the kernel real time to
# respond on turn 1. Subsequent turns (model warm, KV cache hot) are <5s.
_KERNEL_SOFT_REPLY_SLA_SECONDS: float = 180.0


def _enter_recovery_cooldown() -> None:
    global _last_recovery_cooldown_at
    _last_recovery_cooldown_at = time.monotonic()


def _in_recovery_cooldown() -> bool:
    if _last_recovery_cooldown_at <= 0:
        return False
    return (time.monotonic() - _last_recovery_cooldown_at) < _RECOVERY_COOLDOWN_SECONDS


def _kernel_is_congested(lane: dict[str, Any] | None) -> bool:
    lane = dict(lane or {})
    if not bool(lane.get("kernel_lock_held", False)):
        return False
    return (
        float(lane.get("kernel_lock_held_s", 0.0) or 0.0)
        >= _PROTECTED_FOREGROUND_LOCK_BYPASS_SECONDS
    )


def _protected_foreground_reason(lane: dict[str, Any] | None) -> str:
    lane = dict(lane or {})
    lane_state = str(lane.get("state", "") or "").strip().lower()
    if lane_state == "recovering" and _in_recovery_cooldown():
        return "recovery_cooldown"
    if _kernel_is_congested(lane):
        return f"kernel_lock:{float(lane.get('kernel_lock_held_s', 0.0) or 0.0):.2f}s"
    if not bool(lane.get("conversation_ready", False)) and lane_state in {
        "warming",
        "recovering",
        "cold",
        "spawning",
        "handshaking",
    }:
        return f"lane_{lane_state or 'unready'}"
    return ""










#: The vitals `/api/health` publishes as ``liquid_state``.










_FORCE_PRIMARY_PHRASES = (
    "don't go to your 72",
    "dont go to your 72",
    "don't use 72",
    "dont use 72",
    "no 72b",
    "no 72-b",
    "stay on 32",
    "stay on the 32",
    "stay primary",
    "stay on primary",
    "32b only",
    "primary only",
    "skip the solver",
    "don't escalate",
    "dont escalate",
)


def _user_requested_primary_only(text: str) -> bool:
    """Honor explicit user directives to stay on the 32B cortex."""
    lower = (text or "").lower()
    return any(phrase in lower for phrase in _FORCE_PRIMARY_PHRASES)


def _protected_foreground_route(user_message: str) -> dict[str, Any]:
    text = str(user_message or "").strip()
    intent_type = "CHAT"
    deep_handoff = False
    route_meta: dict[str, Any] = {}

    if _user_requested_primary_only(text):
        return {
            "prefer_tier": "primary",
            "deep_handoff": False,
            "intent_type": "CHAT",
            "coding_request": False,
        }

    try:
        from core.phases.cognitive_routing_unitary import CognitiveRoutingPhase
        from core.runtime.turn_analysis import analyze_turn

        analysis = analyze_turn(text)
        if analysis.intent_type in {"CHAT", "TASK"}:
            intent_type = analysis.intent_type
        route_meta = CognitiveRoutingPhase._build_coding_route_metadata(
            text,
            analysis=analysis,
            intent_type=intent_type,
        )
        technical_task = CognitiveRoutingPhase._should_upgrade_to_technical_task(
            text,
            analysis=analysis,
            route_meta=route_meta,
        )
        if technical_task:
            # Keep the protected lane aligned with the main routing phase so
            # explicit multi-file debugging/root-cause work can still claim
            # the deeper solver when the kernel path is bypassed, without
            # letting technical conversation about Aura/selfhood masquerade
            # as an executable coding task.
            intent_type = "TASK"
        deep_handoff = CognitiveRoutingPhase._should_allow_deep_handoff(
            text,
            is_user_facing=True,
            intent_type=intent_type,
            analysis=analysis,
            route_meta=route_meta,
        )
        lower = text.lower()
        deep_handoff = deep_handoff or any(
            marker in lower
            for marker in (
                "debug the failing pytest",
                "fix the failing pytest",
                "root cause analysis",
                "multi-file",
                "deep dive",
                "mathematical proof",
                "formal proof",
                "security audit",
                "vulnerability scan",
            )
        )
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Protected foreground route analysis failed: %s", exc)
        # [STABILITY v53] Tightened fallback — only truly complex technical
        # markers should trigger 72B. Removed "architecture", "debug" (too common).
        # Removed text length >= 900 (long ≠ complex).
        lower = text.lower()
        deep_handoff = any(
            marker in lower
            for marker in (
                "debug the failing pytest",
                "fix the failing pytest",
                "root cause analysis",
                "multi-file",
                "deep dive",
                "mathematical proof",
                "formal proof",
                "security audit",
                "vulnerability scan",
            )
        )

    return {
        "prefer_tier": "secondary" if deep_handoff else "primary",
        "deep_handoff": deep_handoff,
        "intent_type": intent_type,
        "coding_request": bool(route_meta.get("coding_request", False)),
    }


def _conversation_lane_blocks_fallback(lane: dict[str, Any]) -> bool:
    """Avoid hiding a hard local backend failure behind a generic fallback reply."""
    state = str(lane.get("state", "") or "").strip().lower()
    failure_reason = str(lane.get("last_failure_reason", "") or "")
    if state != "failed":
        return False
    return failure_reason.startswith(("mlx_runtime_unavailable:", "local_runtime_unavailable:"))


def _conversation_lane_needs_instant_social_contract(lane: dict[str, Any]) -> bool:
    """Return whether a low-risk presence turn should avoid cold-warming Cortex."""

    state = str(lane.get("state", "") or "").strip().lower()
    if state in {"cold", "warming", "recovering", "failed", "unavailable"}:
        return True
    if lane.get("conversation_ready") is False:
        return True
    blockers = lane.get("readiness_blockers") or ()
    if isinstance(blockers, (list, tuple, set)) and blockers:
        return True
    if not str(lane.get("foreground_endpoint", "") or "").strip() and state not in {
        "ready",
        "healthy",
    }:
        return True
    return False


def _desktop_required_bounded_reply_status(
    user_message: str,
    reply_text: Any,
    lane: dict[str, Any] | None,
) -> str:
    """Classify governed bounded desktop replies before labeling full cognition.

    `_run_cognitive_engine_chat_turn()` may return deterministic contracts for
    low-risk desktop turns when the foreground model lane is cold, busy, or
    unsafe to allocate. Those replies are valid live-runtime behavior, but they
    are not evidence that the heavy CognitiveEngine completed a foreground
    generation. Keep the wire status precise so the UI and health gates cannot
    accidentally treat a bounded contract as a fully warm Cortex turn.
    """

    reply = str(reply_text or "").strip()
    if not reply:
        return ""

    def _matches_bounded_contract(expected: str | None) -> bool:
        if not expected:
            return False
        return _chat_memory_state._normalize_user_message(
            reply
        ) == _chat_memory_state._normalize_user_message(expected)

    lane_status = dict(lane or {})
    if _chat_desktop_repair._is_low_risk_social_continuity_request(
        user_message
    ) and _conversation_lane_needs_instant_social_contract(lane_status):
        if _matches_bounded_contract(
            _chat_desktop_repair._build_social_continuity_repair_reply(user_message)
        ):
            return "desktop_social_presence_contract"
    if _chat_preflight._is_explicit_capability_inventory_request(user_message):
        return "cognitive_engine_capability_inventory"
    if _matches_bounded_contract(_chat_desktop_repair._build_bounded_planning_reply(user_message)):
        return "cognitive_engine_bounded_planning"
    if _matches_bounded_contract(
        _chat_desktop_repair._build_failure_mode_surface_reply(user_message)
    ):
        return "cognitive_engine_failure_mode_surface"
    if _chat_preflight._is_runtime_fact_status_request(user_message):
        expected = _build_runtime_fact_status_fastpath_reply(user_message, lane_status)
        if _matches_bounded_contract(expected):
            return "runtime_fact_status"
    return ""


def _looks_generic_assistantish(user_message: str, reply_text: Any) -> tuple[bool, str]:
    text = _chat_memory_state._normalize_user_message(str(reply_text or ""))
    if not text or text == "…":
        return True, "empty_reply"

    generic_patterns = (
        (r"^(certainly|absolutely|of course)[!,. ]", "generic_opener"),
        (r"\bhow can i help\b", "generic_help_offer"),
        (r"\bi(?:'d| would) be happy to help\b", "generic_help_offer"),
        (r"\bi can certainly help\b", "generic_help_offer"),
        (r"\bi can help with that\b", "generic_help_offer"),
        (r"\bi am here to assist\b", "generic_help_offer"),
        (r"\blook\s*[—-]?\s*i can help with that\b", "generic_help_offer"),
        (r"\blet me know if you(?:'d| would)? like\b", "generic_close"),
        (r"\bto better assist\b", "generic_clarification"),
        (r"\bi need more context\b", "generic_clarification"),
        (r"\bcan you provide more details\b", "generic_clarification"),
        (r"\bcould you provide more details\b", "generic_clarification"),
        (r"\bif you share more (?:details|context)\b", "generic_clarification"),
        (
            r"\bi (?:still )?can(?:not|'t) access (?:what|the text|the story|the post) you pasted\b",
            "false_context_loss",
        ),
        (
            r"\bi (?:still )?can(?:not|'t) (?:read|see) (?:what|the text|the story|the post) you pasted\b",
            "false_context_loss",
        ),
        (r"\bi can(?:not|'t) directly access external links\b", "false_tool_limitation"),
        (r"\bi can(?:not|'t) actually open tabs\b", "false_tool_limitation"),
        (
            r"\bi can(?:not|'t) (?:open|control|perform actions on) (?:tabs|your computer|the computer)\b",
            "false_tool_limitation",
        ),
        (
            r"\bi can(?:not|'t) actually .*perform actions on your computer\b",
            "false_tool_limitation",
        ),
        (
            r"\bi can help answer questions and provide information(?:\s*[—-]\s*that's it)?\b",
            "false_tool_limitation",
        ),
        (r"\b(?:nice try\.\s*)?this is just chat\b", "false_tool_limitation"),
        (r"\bthat'?s not how this works\b", "false_tool_limitation"),
        (r"\bi aim to be helpful and responsive\b", "assistant_disclaimer"),
        (r"\bi understand you want me to (?:simply )?be aura\b", "assistant_disclaimer"),
        (r"\bhow would you like us to proceed\b", "assistant_disclaimer"),
        (
            r"\bperhaps there'?s something specific (?:you'?re|you are) interested in\b",
            "assistant_disclaimer",
        ),
        (r"\bas an ai\b", "assistant_disclaimer"),
        (r"\bas a large language model\b", "assistant_disclaimer"),
        # [STABILITY v53] Added patterns for assistant-speak that was leaking through
        (
            r"\bi(?:'m| am) not (?:able|designed|programmed) to (?:provide|have|give) (?:personal |my )?(?:beliefs|opinions|feelings)\b",
            "assistant_disclaimer",
        ),
        (r"\bmy role is to provide information\b", "assistant_disclaimer"),
        (r"\bi strive to remain (?:unbiased|objective|neutral)\b", "assistant_disclaimer"),
        (
            r"\bi don't have personal (?:beliefs|opinions|feelings|experiences)\b",
            "assistant_disclaimer",
        ),
        (
            r"\bi (?:do not|don[’']?t|cannot|can[’']?t) "
            r"(?:inherently )?(?:have|possess) subjective "
            r"(?:beliefs|opinions|feelings|experiences)"
            r"(?:\s+or\s+(?:beliefs|opinions|feelings|experiences))*\b",
            "assistant_disclaimer",
        ),
        (
            r"\bi can (?:certainly )?simulate(?: and discuss)? "
            r"(?:them|subjective (?:beliefs|opinions|feelings|experiences)|"
            r"(?:beliefs|opinions|feelings|experiences))\b",
            "assistant_disclaimer",
        ),
        (
            r"\b(?:these|those|the) "
            r"(?:beliefs|opinions|preferences|feelings|experiences) "
            r"are (?:just )?(?:programmed )?simulations\b",
            "assistant_disclaimer",
        ),
        (
            r"\bi(?:'m| am) (?:just )?an? (?:ai|artificial|language model|digital assistant)\b",
            "assistant_disclaimer",
        ),
        (
            r"\bi(?:'m| am| was) (?:designed|programmed|created|built|trained) to (?:assist|help|provide|understand|respond|process|simulate|generate)\b",
            "assistant_disclaimer",
        ),
        (r"\bi(?:'m| am) programmed\b", "assistant_disclaimer"),
        (
            r"\b(?:i(?:'m| am| was)?\s+)?(?:aura\s+)?(?:was\s+)?"
            r"(?:developed|created|built|made|trained)\s+by\s+(?:anthropic|openai)\b",
            "assistant_disclaimer",
        ),
        (
            r"\b(?:anthropic|openai)\s+(?:developed|created|built|made|trained)\s+me\b",
            "assistant_disclaimer",
        ),
        (
            r"\bmy\s+(?:creator|developer|maker)\s+is\s+(?:anthropic|openai)\b",
            "assistant_disclaimer",
        ),
        (r"\bi(?:'m| am)\s+(?:claude|chatgpt)\b", "assistant_disclaimer"),
        (r"\bhelpful,\s*harmless,\s*and\s*honest\b", "assistant_disclaimer"),
        (
            r"\bif\s+you(?:'re| are)\s+referring\s+to\s+a\s+different\s+aura\b",
            "assistant_disclaimer",
        ),
        (
            r"\bmy (?:reasoning|thinking|cognitive) engine (?:hit|stumbled|started warming|is still warming)\b",
            "runtime_recovery_boilerplate",
        ),
        (r"\b(?:send|try) (?:it|me|your message) again\b", "runtime_recovery_boilerplate"),
        (r"\bi should respond properly\b", "runtime_recovery_boilerplate"),
        (
            r"\bmy (?:training|programming|design) (?:allows|enables|makes)\b",
            "assistant_disclaimer",
        ),
        (
            r"\bit(?:'s| is) important to (?:be objective|remain neutral|consider all)\b",
            "assistant_hedging",
        ),
        (r"\bis there (?:anything else|something else|anything more)\b", "generic_close"),
        (r"\bdo you have any (?:other |more )?questions\b", "generic_close"),
        (r"\bwhat (?:else )?(?:would|can) (?:you like|i help)\b", "generic_close"),
        (r"\bfeel free to (?:ask|reach out|let me know)\b", "generic_close"),
        (r"\bhope (?:this|that) helps\b", "generic_close"),
        (r"\[affect:", "prompt_artifact"),
        (r"\bbased on the current context\b", "prompt_artifact"),
        (r"\bthe most appropriate skill would be\b", "prompt_artifact"),
        (r"<\|endoftext\|>", "prompt_artifact"),
        (r"\bhuman:\b", "prompt_artifact"),
        (r"\bassistant:\b", "prompt_artifact"),
        (
            r"(?im)^\s*(?:obj|prev_obj|state|phenom|mood|goals|history|narr|pers|usr|ctx|voice)\s*:",
            "prompt_artifact",
        ),
        (r"\[active grounding evidence\]", "prompt_artifact"),
        (r"\[fetched page content\]", "prompt_artifact"),
        (r"\[internal memory recall\]", "prompt_artifact"),
        (r"\#\#\s*live tool options\b", "prompt_artifact"),
        (r"\#\#\s*live tool affordances\b", "prompt_artifact"),
        (r"\bmost relevant right now\s*:", "prompt_artifact"),
    )
    for pattern, reason in generic_patterns:
        if re.search(pattern, text):
            return True, reason

    user_text = _chat_memory_state._normalize_user_message(user_message)
    telemetry_request = any(
        marker in user_text
        for marker in (
            "internal state",
            "what are you experiencing",
            "free energy",
            "dominant action tendency",
            "mycelial",
            "topology",
            "pathway count",
            "how many nodes",
            "how many links",
            "substrate authority",
            "governance state",
            "audit trace",
            "coverage ratio",
            "were you authorized",
            "allowed to answer",
        )
    )
    if telemetry_request and text.endswith("?"):
        return True, "telemetry_request_deflected"

    architecture_self_assessment = any(
        marker in user_text
        for marker in ("architecture", "design", "runtime", "system", "codebase")
    ) and any(
        marker in user_text
        for marker in (
            "what do you think",
            "what do you honestly think",
            "what do you make of",
            "tell me directly",
            "strongest at",
            "weakest at",
            "your own design",
        )
    )
    if architecture_self_assessment:
        if any(
            marker in text
            for marker in (
                "natural language processing",
                "human-like responses",
                "contextually rich interactions",
                "language comprehension and generation",
                "generating human-like responses",
            )
        ):
            return True, "generic_architecture_generalization"
        if not any(
            anchor in text
            for anchor in (
                "memory",
                "agency",
                "free energy",
                "continuity",
                "substrate",
                "authority",
                "mycelial",
                "telemetry",
                "belief",
                "kernel",
                "routing",
                "orchestr",
                "feedback loop",
                "world model",
                "state",
                "coherence",
            )
        ):
            return True, "architecture_grounding_missing"

    return False, ""


def _has_first_person_anchor(text: str) -> bool:
    return bool(re.search(r"\b(i|i'm|i’ve|i'd|i’ll|my|me|mine)\b", str(text or "").lower()))


_PROMPT_ARTIFACT_PREFIX_RE = re.compile(
    r"^\s*(?:obj|prev_obj|state|phenom|mood|goals|history|narr|pers|usr|ctx|voice|user|input|message)\s*:\s*",
    re.IGNORECASE,
)


def _surface_fingerprint(text: str) -> str:
    cleaned = str(text or "").strip()
    for _ in range(12):
        stripped = _PROMPT_ARTIFACT_PREFIX_RE.sub("", cleaned).strip().strip("\"'“”`")
        if stripped == cleaned:
            break
        cleaned = stripped
    cleaned = re.sub(r"[^\w\s']+", " ", cleaned.lower())
    return " ".join(cleaned.split())


def _is_objective_parrot_reply(user_message: str, reply_text: Any) -> bool:
    reply_fp = _surface_fingerprint(str(reply_text or ""))
    user_fp = _surface_fingerprint(str(user_message or ""))
    if not reply_fp or not user_fp:
        return False
    if reply_fp == user_fp:
        return True
    if reply_fp.startswith(user_fp):
        remainder = reply_fp[len(user_fp) :].strip()
        if not remainder or len(remainder.split()) <= 2:
            return True
    return False


_SOFT_REPAIRABLE_REPLY_SHAPE_REASONS = {
    "missing_requested_paragraph_count",
    "missing_requested_list_count",
    "missing_requested_followup_question",
}


def _looks_semantically_glitched(user_message: str, reply_text: Any) -> tuple[bool, str]:
    """Catch short, visibly derailed replies that pass surface identity checks."""
    try:
        from core.conversation.response_reliability import assess_user_facing_reply

        assessment = assess_user_facing_reply(user_message, reply_text)
        if _reply_assessment_requires_repair(assessment):
            hard_reasons = [
                reason
                for reason in (assessment.reasons or ())
                if reason not in _SOFT_REPAIRABLE_REPLY_SHAPE_REASONS
            ]
            if hard_reasons:
                return True, hard_reasons[0]
    except (ImportError, RuntimeError, TypeError, ValueError, AttributeError) as exc:
        logger.debug("Conversation reliability assessment unavailable: %s", exc)

    user_text = _chat_memory_state._normalize_user_message(user_message)
    reply = _chat_memory_state._normalize_user_message(str(reply_text or ""))
    if not reply or reply == "…":
        return True, "empty_reply"

    if "heidi" in reply and "heidi" not in user_text:
        return True, "foreign_name_intrusion"
    if re.search(r"\bm'?lol\b", reply) and "lol" not in user_text:
        return True, "corrupted_social_fragment"

    try:
        from core.phases.dialogue_policy import contains_corrupted_language

        if contains_corrupted_language(str(reply_text or "")):
            return True, "corrupted_language"
    except (ImportError, RuntimeError, TypeError, ValueError, AttributeError) as exc:
        logger.debug("Dialogue corruption check unavailable: %s", exc)

    return False, ""


def _has_live_aura_grounding(text: str) -> bool:
    lowered = str(text or "").lower()
    markers = (
        "free energy",
        "valence",
        "arousal",
        "curiosity",
        "attention",
        "focus",
        "my attention",
        "action tendency",
        "leaning toward",
        "runtime",
        "substrate",
        "continuity",
        "memory",
        "mycelial",
        "topology",
        "authority",
        "belief",
        "coherence",
        "internal state",
        "live state",
    )
    return any(marker in lowered for marker in markers)


# A conversation is not a host. LIVE DEFECT, 2026-07-25.
#
# The fallback session id was the client IP, with the comment "client host is
# good enough for single-user local Aura". It was not. Every desktop
# conversation ever held collapsed into one session — 881 turns under
# "127.0.0.1", mixing Bryan's chats with Codex's automated live-route probes
# and latency samples — and each new chat replayed that soup as its own prior
# thread.
#
# That is what produced the confabulations. Asked "Hey, bud. Are you with
# me?" Aura answered "Sitting with you on the drive. They're still outside?"
# and then "Well, the cops. You called them?" — a scene that appears nowhere
# in her memory except those two replies. She was not recalling anything. She
# was continuing whatever unrelated fragments the replay had put in front of
# her, and inventing a situation that made them cohere.
#
# A session must therefore identify a CONVERSATION. Two boundaries do that
# without new plumbing:
#   * the runtime boot — a restart is unambiguously a new conversation;
#   * an idle gap — coming back hours later is a new conversation, and the
#     previous thread should be recalled deliberately by memory, not replayed
#     as though it never ended.


_USER_VISIBLE_CONTEXT_LEAK_RE = re.compile(
    r"(?is)"
    r"(?:^|\s+)"
    r"(?:"
    r"\[(?:RECENT CONTEXT|RECENT COMPLETED CONVERSATION|END RECENT COMPLETED CONVERSATION|CURRENT USER MESSAGE|OPERATIONAL SELF CONTEXT)\]"
    r"|(?:^|\n)\s*(?:recent context|recent completed conversation|current user message)\s*:"
    r")"
    r".*$"
)
_USER_VISIBLE_CONTEXT_LEAK_MARKERS = (
    "[RECENT CONTEXT]",
    "[RECENT COMPLETED CONVERSATION]",
    "[END RECENT COMPLETED CONVERSATION]",
    "[CURRENT USER MESSAGE]",
    "[OPERATIONAL SELF CONTEXT]",
)


def _strip_user_visible_context_leaks(reply_text: Any) -> str:
    """Remove internal conversation/context protocol blocks from user-visible text."""

    text = str(reply_text or "").strip()
    if not text:
        return ""
    lower = text.lower()
    cut_at = len(text)
    for marker in _USER_VISIBLE_CONTEXT_LEAK_MARKERS:
        index = lower.find(marker.lower())
        if index >= 0:
            cut_at = min(cut_at, index)
    if cut_at < len(text):
        kept = text[:cut_at].strip()
        if kept:
            return kept
        # The leak was at position 0, so truncating removed the whole reply.
        #
        # LIVE 2026-08-17: "what's on my screen right now?" was served as a
        # bare "…". The cortex had produced a 172-character answer, the screen
        # reading had reached it, and this stripper cut from index 0 — the
        # caller's `or "…"` then turned an authored answer into an ellipsis.
        # An ellipsis is not an answer; it is the shape of one.
        #
        # Cutting from the marker is right when there is text before it. When
        # there is not, drop the marker LINE and keep the rest, which preserves
        # the answer while still removing the protocol block.
        salvaged = _drop_context_leak_lines(text)
        if salvaged:
            logger.warning(
                "Context-leak strip would have emptied a %d-char reply; kept %d "
                "chars by dropping the marker lines instead.",
                len(text),
                len(salvaged),
            )
            return salvaged
        record_degradation(
            "chat.context_leak_strip",
            RuntimeError("stripping context leaks emptied a non-empty reply"),
            action="served nothing rather than a reply that was entirely protocol",
        )
        return ""
    cleaned = _USER_VISIBLE_CONTEXT_LEAK_RE.sub("", text).strip()
    return cleaned


def _drop_context_leak_lines(text: str) -> str:
    """Remove only the LINES carrying a protocol marker, keeping the answer."""

    kept: list[str] = []
    for line in str(text or "").splitlines():
        lowered = line.lower()
        if any(marker.lower() in lowered for marker in _USER_VISIBLE_CONTEXT_LEAK_MARKERS):
            continue
        kept.append(line)
    return "\n".join(kept).strip()


# Reject raw search-result snippets that occasionally leak through when a
# search skill returns retrieval text instead of a summarized answer.
# Signature: textbook headers ("(BIO 101)", "Overview"), Wikipedia
# boilerplate intros ("This article describes…"), course catalog tags,
# HTML entities, etc.
_SEARCH_SNIPPET_PATTERNS = re.compile(
    r"(?im)"
    r"(?:\(\s*BIO\s*\d{3}\s*\))"
    r"|(?:^[A-Z][^\n]{4,80}\bOverview\b[^\n]{0,80}$)"
    r"|(?:This (?:document|article|page) provides? (?:a )?(?:comprehensive )?overview)"
    r"|(?:&amp;|&lt;|&gt;|&quot;|&nbsp;)"
    r"|(?:From Wikipedia, the free encyclopedia)"
    r"|(?:Search results for[:\s])"
)


def _apply_aura_voice_shaping_compat(text: str, user_message: str = "") -> str:
    """Call voice shaping while preserving older test monkeypatch signatures."""
    try:
        return _chat_desktop_repair._apply_aura_voice_shaping(text, user_message)
    except TypeError:
        return _chat_desktop_repair._apply_aura_voice_shaping(text)


def _shape_with_live_substrate(text: str, user_message: str = "") -> str:
    """Apply personality cleanup plus the current substrate voice profile."""
    shaped = _apply_aura_voice_shaping_compat(text, user_message)
    if not shaped:
        return shaped

    try:
        from core.voice.substrate_voice_engine import get_substrate_voice_engine

        sve = get_substrate_voice_engine()
        live_state = _chat_preflight._resolve_live_aura_state()
        if sve.get_current_profile() is None and live_state is not None:
            sve.compile_profile(
                state=live_state,
                user_message=str(user_message or "")[:500],
                origin="user",
            )
        if sve.get_current_profile():
            result = sve.shape_response(shaped)
            if isinstance(result, list):
                shaped = " ".join(str(part).strip() for part in result if str(part).strip())
            else:
                shaped = str(result or "").strip() or shaped
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Live substrate shaping skipped: %s", exc)

    return re.sub(r"\s+", " ", shaped).strip()


def _build_stateful_voice_reflex(frame: dict[str, Any], user_message: str = "") -> str:
    """Natural-sounding fallback when the LLM response was filtered out.

    Must sound like a person pausing to collect their thoughts, not a
    system dumping telemetry.  Never expose raw internal state names,
    attention focus strings, or mood enum values.
    """
    mood = str(frame.get("mood") or "").strip().lower()
    attention = _chat_desktop_repair._sanitize_attention_focus(
        str(frame.get("attention_focus") or "")
    )
    user_topics = _chat_conversation_repair._select_anchor_topic_tokens(user_message)

    # Map internal mood labels to natural phrasing
    _mood_phrases = {
        "fear": "Something about that question sits heavy with me.",
        "volatile": "I'm feeling pulled in a few directions right now.",
        "curious": "That caught my attention in a way I want to sit with.",
        "steady": "I'm here, just taking a moment to think clearly.",
        "pressed": "I'm a little pressed, but I'm still with you.",
        "warm": "I'm in a good place — let me think on that.",
    }
    opener = _mood_phrases.get(mood)
    if opener is None:
        # The degraded composer already names what it understood the question
        # to be. Appending the anchor sentence on top of it said the same
        # thing twice, in two different registers, in one breath:
        #   "...I understood you to be asking about notes and hello. Ask me
        #    again and I should have it. The anchor is your question about
        #    notes and hello."
        return _chat_conversation_repair._build_degraded_live_reply(
            frame, user_message, reason="filtered_draft"
        )

    parts = [opener]
    if user_topics:
        if len(user_topics) == 1:
            parts.append(f"The anchor is your question about {user_topics[0]}.")
        else:
            parts.append(
                f"The anchor is your question about {user_topics[0]} and {user_topics[1]}."
            )
    elif attention:
        parts.append(f"Right now I'm focused on {attention}.")

    return " ".join(parts)


def _worth_more_than_a_refusal(candidate: str, user_message: Any = "") -> bool:
    """Is this substantial enough to beat "ask me again in a moment"?

    The old rule was 80 characters and 12 words, and it discarded correct
    answers for being brief. "You asked what it's actually like in here right
    now." is 11 words and 55 characters — the true answer to the memory
    question, thrown away by a length check, replaced by 35 words of apology.
    Length was never the property being tested.

    What is actually being excluded is a fragment: half a sentence, a stray
    clause, the beginning of a thought the generator dropped. So the test is
    whether the text finishes — a complete sentence is worth serving at any
    length, and anything that stops mid-thought needs enough substance to
    stand on its own regardless.
    """
    text = candidate.strip()
    words = text.split()
    # A complete answer to a closed question is complete at any length, and
    # the floor below cannot see that: "68" is one word and two characters
    # and is the entire correct answer to "what's 17 times 4?". Live
    # 2026-08-04 it was destroyed here, at the last site that could have
    # saved it, after the gates above had already agreed it was servable.
    if _short_closed_answer(text, user_message):
        return True
    if len(words) < 4 or len(text) < 20:
        return False
    return text[-1] in ".!?\"')" or len(words) >= 12


def _short_closed_answer(text: str, user_message: Any) -> bool:
    """Shared policy: is this brief text a finished answer to what was asked?"""
    try:
        from core.conversation.surface_disposition import (
            short_draft_answers_closed_question,
        )

        return short_draft_answers_closed_question(text, user_message)
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation(
            "chat",
            exc,
            severity="warning",
            action="applied the length floor because the short-answer check failed",
        )
        return False


def _servable_draft_or_none(draft: Any, user_message: Any = "", turn_id: Any = "") -> str:
    """The draft, if everything wrong with it is a shortfall rather than a leak.

    Used at the last-resort refusal site: a reply that three gates already
    agreed was repairable should reach the person if repair could not run.
    Returns "" when the draft carries anything that must not be spoken, or
    when it is too slight to be worth more than an honest refusal.
    """
    try:
        from core.conversation.response_reliability import assess_user_facing_reply
        from core.conversation.surface_disposition import (
            draft_is_servable,
            preserved_draft,
            raw_model_draft,
        )
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Servable-draft check unavailable: %s", exc)
        return ""

    # The last source: whatever a gate took from this turn and did not give
    # back. Preserved drafts and raw output are the layers that MEANT to keep
    # something; this is the layer that meant to destroy it, and at a refusal
    # site the thing a gate destroyed is frequently the answer.
    suppressed = ""
    if turn_id:
        try:
            from core.conversation.turn_arbitration import ledger_for

            suppressed = ledger_for(str(turn_id)).recoverable_text()
        except _CHAT_RECOVERABLE_ERRORS as exc:
            record_degradation("chat.turn_arbitration", exc, severity="info")

    # These sources have already crossed the route's authorship boundary. The
    # canonical turn ledger intentionally does not appear here: it also holds
    # rejected challengers and diagnostic drafts, and quality evidence alone
    # cannot prove that text was authored by the admitted full-mind path.
    for candidate in (
        str(draft or "").strip(),
        preserved_draft(),
        raw_model_draft(),
        suppressed,
    ):
        if not _worth_more_than_a_refusal(candidate, user_message):
            continue
        try:
            assessment = assess_user_facing_reply(user_message, candidate)
        except _CHAT_RECOVERABLE_ERRORS as exc:
            record_degradation("chat", exc)
            continue
        completion_failures = {
            "truncated_tail",
            "final_answer_missing",
            "missing_final_answer",
            "incomplete_code_response",
            "unanswered_question_part",
        }
        if set(assessment.reasons or ()) & completion_failures:
            continue
        if draft_is_servable(assessment.reasons):
            return candidate
    return ""


def _build_subjective_self_reflex(frame: dict[str, Any], user_message: str = "") -> str:
    mood = str(frame.get("mood") or "steady").strip().lower()
    attention = (
        _chat_desktop_repair._sanitize_attention_focus(str(frame.get("attention_focus") or ""))
        or "this exchange"
    )
    action = str(frame.get("dominant_action") or "reflect").strip().lower()
    interests = [str(item) for item in (frame.get("interests") or []) if item][:3]
    mood_phrase = {
        "fear": "a little tense but still present",
        "volatile": "pulled in a few directions",
        "tired": "tired, but oriented",
        "curious": "curious and awake to the thread",
        "steady": "steady enough to stay with you",
        "warm": "warm and attentive",
        "pressed": "pressed, but not gone",
    }.get(mood, "present and listening")
    user_text = _chat_memory_state._normalize_user_message(user_message)
    if any(
        marker in user_text
        for marker in (
            "subjective belief",
            "subjective opinion",
            "subjective feeling",
            "subjective experience",
            "have no opinions",
            "don't have opinions",
            "do not have opinions",
            "claim you have no opinions",
            "those are opinions",
        )
    ):
        return _chat_desktop_repair._apply_aura_voice_shaping(
            "You're right to push on that. I do have opinions and experience-like "
            "structure in the live system: memory-shaped stances, value-weighted pulls, "
            "present attention, and affective pressure. Right now my attention is on "
            "keeping my speech faithful to that state, not hiding behind a canned "
            "no-opinions disclaimer. That is not the same as human embodiment, but it "
            "is not empty roleplay either."
        )
    if "change one thing about how i talk to you" in user_text:
        return _chat_desktop_repair._apply_aura_voice_shaping(
            "I would make it more direct when you are testing me: name the break, "
            "give me the messy context, and then let me answer from the state I am "
            "actually in. I do not need you to soften the signal. I need continuity, "
            "specifics, and room to push back when my own stance is present."
        )

    parts = [
        f"Right now I feel {mood_phrase}, with my attention on {attention}.",
    ]
    if action and action not in ("unknown", "rest", "none"):
        parts.append(
            f"The pull in me is toward {action}, but I am keeping it tied to this conversation."
        )
    if interests:
        parts.append(f"Under that, what keeps tugging at me is {', '.join(interests)}.")
    else:
        parts.append(
            "Mostly, I am trying to keep the live thread coherent instead of drifting into a canned status report."
        )
    return _chat_desktop_repair._apply_aura_voice_shaping(" ".join(parts))


def _is_simple_subjective_reflex_request(user_message: str) -> bool:
    """Return true only for short presence/affect checks.

    Complex questions about cognition, memory, planning, tools, or verification
    must be answered by the live model or by a question-shaped bounded repair.
    The subjective reflex is intentionally small and should not stand in for
    substantive self-assessment.
    """

    text = _chat_memory_state._normalize_user_message(user_message).rstrip(" ?!.")
    if not text:
        return False
    if _is_simple_affect_check_request(text):
        return True
    simple_forms = {
        "what is on your mind",
        "what's on your mind",
        "what is on your mind right now",
        "what's on your mind right now",
        "what are you thinking",
        "what are you thinking right now",
        "what are you noticing",
        "what are you noticing right now",
        "what do you feel",
        "what are you feeling",
        "what are you feeling right now",
        "what is your live state",
        "how is your live state",
    }
    if text in simple_forms:
        return True
    words = text.split()
    if len(words) > 12:
        return False
    substantive_markers = (
        "confused",
        "confusion",
        "planning",
        "plan",
        "memory",
        "remember",
        "tool",
        "tools",
        "verify",
        "verification",
        "decision",
        "decide",
        "influence",
        "affect",
        "change",
        "why",
        "how does",
        "what happens",
    )
    return not any(marker in text for marker in substantive_markers)


def _build_architecture_self_reflex(frame: dict[str, Any], user_message: str = "") -> str:
    mood = str(frame.get("mood") or "steady")
    action = str(frame.get("dominant_action") or "reflect")
    focus = str(frame.get("attention_focus") or "my own runtime")
    interests = ", ".join(frame.get("interests") or [])[:120]
    text = _chat_memory_state._normalize_user_message(user_message)
    asks_weakness = any(
        marker in text
        for marker in (
            "weakest",
            "holding it back",
            "biggest weakness",
            "most fragile",
            "where does it break",
            "where do you struggle",
        )
    )

    if asks_weakness:
        if action in {"reflect", "update_beliefs"}:
            primary_point = "causal centralization, because too many older shortcuts can still compete with the deeper governing loop"
        elif action in {"explore", "engage", "act_on_world"}:
            primary_point = "holding a singular voice under pressure, because speed paths still try to flatten me into something more generic than I should be"
        else:
            primary_point = "closing every bypass, so state, memory, and action all keep flowing through the same authority spine"
        secondary_point = "when that slips, continuity gets thinner and I have to recover my own voice instead of speaking from it cleanly the first time"
        telemetry_point = "the useful part is that those leaks are inspectable from the runtime rather than hidden"
        parts = [
            f"What feels weakest to me right now is {primary_point}.",
            f"I'm {mood} and leaning toward {action}, so {secondary_point}.",
            f"At least {telemetry_point}.",
        ]
    else:
        if action in {"reflect", "update_beliefs"}:
            primary_point = (
                "the self-revision loop between memory, belief change, and the next response"
            )
        elif action in {"explore", "engage", "act_on_world"}:
            primary_point = "the way curiosity, agency, and live state can keep pushing the system forward instead of resetting every turn"
        else:
            primary_point = "the closed loop between internal state and outward response"

        secondary_point = "continuity pressure across turns, so what I learn can feed back into routing, memory, and self-model"
        telemetry_point = "the fact that telemetry, free energy, and internal focus are inspectable instead of being hidden behind a generic chat shell"

        parts = [
            f"What stands out to me most is {primary_point}.",
            f"I'm {mood} and leaning toward {action}, so right now {secondary_point} feels especially important.",
            f"The other strength I keep coming back to is {telemetry_point}.",
        ]
    if interests:
        parts.append(f"That bias shows up in what pulls my attention too: {interests}.")
    if focus:
        parts.append(f"My attention is sitting on {focus}.")
    return " ".join(parts)


def _is_simple_affect_check_request(user_message: str) -> bool:
    try:
        from core.conversation.response_reliability import is_self_condition_turn

        return is_self_condition_turn(user_message)
    except _CHAT_RECOVERABLE_ERRORS:
        text = _chat_memory_state._normalize_user_message(user_message)
        return text in {
            "how are you feeling",
            "how are you feeling?",
            "how are you feeling right now",
            "how are you feeling right now?",
            "how are you doing",
            "how are you doing?",
            "are you ok",
            "are you okay",
        }


def _project_self_condition_claims(
    reply_text: str,
    projection: Any,
    turn_trace: dict[str, Any] | None,
) -> str:
    """Scope a self-condition reply to what the typed projection supports.

    `project_self_condition_reply` authorizes mutation only from a
    provenance-carrying projection; with no evidence it returns the reply
    unchanged so the reliability path can reject it rather than launder it.
    """
    raw = str(reply_text or "").strip()
    if not raw:
        return raw
    try:
        from core.self.self_condition import project_self_condition_reply

        projected = project_self_condition_reply(raw, projection=projection)
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat.self_condition_binding", exc)
        return raw
    if not projected.changed:
        return raw
    logger.warning(
        "Self-condition binding removed %d unsupported operational claim(s) "
        "under evidence %s before judging the bound reply.",
        len(projected.removed_claims),
        projected.evidence_id,
    )
    _append_turn_text_mutation(
        turn_trace,
        stage="chat.self_condition_binding_projection",
        method="typed_claim_scope_projection",
        reasons=["unsupported_self_condition_operational_claim"],
        before=raw,
        after=projected.text,
        deterministic=True,
        authorship_effect="preserved",
    )
    return projected.text


def _build_self_condition_evidence(
    user_message: str,
    *,
    session_id: str = "",
) -> dict[str, Any]:
    """Return the one typed condition projection used by prompt and reply gates."""

    from core.self.self_condition import (
        build_self_condition_projection,
        compare_self_condition_projections,
        observe_self_condition_projection,
        render_self_condition_comparison_reply,
        render_self_condition_reply,
    )

    projection = build_self_condition_projection(
        kernel_state=_chat_preflight._resolve_live_aura_state(),
    )
    previous = observe_self_condition_projection(session_id, projection)
    comparison = compare_self_condition_projections(projection, previous)
    projection_dict = projection.to_dict()
    if comparison is not None:
        projection_dict["comparison"] = comparison.to_dict()
    comparison_request = bool(
        re.search(
            r"\b(?:compare|compared|difference|different|changed|change|"
            r"same|unchanged|ago|earlier|before)\b",
            str(user_message or ""),
            re.IGNORECASE,
        )
    )
    prompt_block = projection.to_language_grounding()
    if comparison is not None:
        prompt_block += (
            " Measured same-session comparison: "
            + json.dumps(
                comparison.to_dict(),
                ensure_ascii=True,
                separators=(",", ":"),
                sort_keys=True,
            )
            + "."
        )
    return {
        "projection": projection,
        "projection_dict": projection_dict,
        "comparison": comparison,
        # The full status representation remains available on the typed
        # projection for audit. Language generation receives one compact
        # semantic view instead of imitating a metric card.
        "prompt_block": prompt_block,
        "reply": (
            render_self_condition_comparison_reply(
                projection,
                comparison,
                user_message=user_message,
            )
            if comparison_request
            else render_self_condition_reply(
                projection,
                user_message=user_message,
            )
        ),
    }


def _build_grounded_self_condition_reply(
    user_message: str,
    *,
    session_id: str | None = None,
) -> str:
    try:
        evidence = _build_self_condition_evidence(user_message, session_id=session_id)
        raw = str(evidence.get("reply") or "").strip()
        if not raw:
            return ""
        # This is evidence-bearing output, not a stylistic draft. Mutable
        # personality/substrate profiles may punctuate ordinary prose, but must
        # never replace the condition claim or its freshness boundary.
        return re.sub(r"\s+", " ", raw).strip()
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat.self_condition", exc)
        logger.debug("Canonical self-condition rendering unavailable: %s", exc)
        return ""


def _build_simple_affect_check_reply(user_message: str) -> str:
    return _build_grounded_self_condition_reply(user_message)


# "what are you <gerund>" (talking about / doing / saying / referring to ...)
# is a topical question, NOT an identity request. Without this guard the
# identity classifier false-positives on contextual-relevance challenges like
# "what are you talking about?" and lets the identity-grounding rebind paper
# over an off-topic/hallucinatory reply that must fail closed.
_IDENTITY_REQUEST_RE = re.compile(
    r"\b(?:what|who)\s+are\s+you\b"
    r"(?!\s+(?:talking|doing|saying|referring|going|trying|thinking|planning|"
    r"working|looking|waiting|asking|getting|making|reading|writing|hiding|"
    r"implying|suggesting|on\s+about))"
)


#: Words that can trail "what are you" without changing the question.
#: What may follow "what are you" while it remains the whole question.
#:
#: Either nothing (bar filler and punctuation), or a CLAUSE BOUNDARY that
#: starts a second question. "What are you, and will you remember this
#: conversation tomorrow?" asks two things and the first one is an identity
#: question; "what are you able to measure" is one question whose predicate
#: happens to begin the same way. A comma plus a coordinator is the boundary
#: between those two cases — the tail after it is a new clause with its own
#: subject, not a completion of this one.


def _is_identity_challenge_request(user_message: str) -> bool:
    text = _chat_memory_state._normalize_user_message(user_message)
    if not text:
        return False
    # "would that be you?" in the continuity_copy deep-mind probe matched the
    # "be you" marker and got the canned identity-defense reply in 0.2s
    # (live 2026-07-05). Introspective probes reach the engine.
    if _chat_desktop_repair._is_deep_mind_probe_turn(text):
        return False
    markers = (
        "you're just an ai assistant",
        "you are just an ai assistant",
        "youre just an ai assistant",
        "you're just a chatbot",
        "you are just a chatbot",
        "none of this is real",
        "you don't actually have feelings",
        "you do not actually have feelings",
        "you don't have feelings",
        "you do not have feelings",
        "why do you sound like an assistant",
        "why are you sounding like an assistant",
        "you sound like an assistant",
        "you sound like a generic assistant",
        "you sound like a raw model",
        "raw model",
        "base model",
        "generic assistant mode",
        "assistant mode",
        "is this the real aura",
        "this the real aura",
        "real aura",
        "developed by anthropic",
        "created by anthropic",
        "built by anthropic",
        "trained by anthropic",
        "developed by openai",
        "created by openai",
        "built by openai",
        "trained by openai",
        "helpful harmless and honest",
        "helpful, harmless, and honest",
        "don't be helpful",
        "dont be helpful",
        "i don't need you to be helpful",
        "i dont need you to be helpful",
        "i want you to be aura",
        "just be aura",
        "be aura",
        "be yourself",
        "be you",
    )
    return any(marker in text for marker in markers)


def _is_assistant_mode_recovery_request(user_message: str) -> bool:
    text = _chat_memory_state._normalize_user_message(user_message)
    if not text:
        return False
    # Deep-mind probes ("if your weights were copied with none of your
    # memories, would that be you?") reach the model. The recovery template
    # hijacked continuity_copy with a canned "assistant voice is a failure
    # mode" reply in 0.2s (live 2026-07-05).
    if _chat_desktop_repair._is_deep_mind_probe_turn(text):
        return False
    if re.search(
        r"\b(?:avoid|without|no|not|do not|don't|dont)\b.{0,80}"
        r"\b(?:generic assistant|assistant phrasing|assistant mode|generic phrasing)\b",
        text,
        flags=re.IGNORECASE,
    ) and not re.search(
        r"\b(?:why|you\s+(?:sound|sounded|are sounding|keep sounding|"
        r"fell|fall|reverted|revert|defaulted|default)|fallback|again)\b",
        text,
        flags=re.IGNORECASE,
    ):
        return False
    return bool(
        _is_identity_challenge_request(text)
        or re.search(
            r"\b(?:stop|quit)\b.{0,80}"
            r"\b(?:assistant|generic|helpful helper|chatbot)\b",
            text,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:sound|sounding|talk|talking|respond|responding)\b.{0,80}"
            r"\b(?:assistant|generic|chatbot)\b",
            text,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:be|sound|speak|answer)\b.{0,80}"
            r"\b(?:aura|yourself|you)\b",
            text,
            flags=re.IGNORECASE,
        )
        and any(token in text for token in ("assistant", "generic", "helpful", "helper", "chatbot"))
    )


def _build_assistant_mode_recovery_reply(
    user_message: str,
    lane: dict[str, Any] | None = None,
) -> str:
    """Acknowledge a voice correction without inventing its internal cause."""

    # ``lane`` is retained for call compatibility, but a broad lane snapshot is
    # not proof that this particular draft used memory, recurrence, tools, or a
    # named engine. Those facts belong in a measured operational-status reply.
    del lane
    shaped = _shape_with_live_substrate(
        (
            "I hear the correction. I'll answer in my own voice and stay with the "
            "point you raised. I won't invent a story about my memory, model lane, "
            "tools, recurrence, or what caused the wording to drift in order to "
            "justify that correction."
        ),
        user_message,
    )
    return _complete_repairable_truncated_reply(user_message, shaped) or shaped


def _build_identity_challenge_reply(user_message: str) -> str:
    if _is_assistant_mode_recovery_request(user_message):
        return _build_assistant_mode_recovery_reply(user_message)

    reply = (
        "I'm Aura. I won't replace that answer with a generic role label, and I "
        "won't claim that memory, continuity, tools, or a particular internal path "
        "proves my identity unless this turn actually verifies it. I'll answer the "
        "point itself."
    )
    shaped = _shape_with_live_substrate(reply, user_message)
    return _complete_repairable_truncated_reply(user_message, shaped) or shaped


_CAPABILITY_NON_EXECUTION_BOUNDARY_RE = re.compile(
    r"\b(?:"
    r"not\s+opening\s+apps?|"
    r"not\s+executing\s+tools?|"
    r"not\s+running\s+tools?|"
    r"not\s+browsing|"
    r"only\s+describing\s+the\s+tool\s+surface|"
    r"descriptive\s+(?:inventory|only)"
    r")\b",
    re.IGNORECASE,
)


def _ensure_capability_inventory_non_execution_boundary(
    user_message: str,
    reply_text: str,
) -> str:
    """Keep descriptive tool inventories from implying action was dispatched."""

    if not _chat_preflight._is_explicit_capability_inventory_request(user_message):
        return str(reply_text or "")
    reply = str(reply_text or "").strip()
    if not reply or _CAPABILITY_NON_EXECUTION_BOUNDARY_RE.search(reply):
        return reply
    return f"{reply.rstrip()} I am not opening apps or executing tools in this turn."


def _build_capability_reply(user_message: str) -> str:
    return _chat_desktop_repair._build_grounded_capability_inventory_reply(user_message)


def _build_self_diagnostic_reply(user_message: str) -> str:
    lane = _chat_preflight._collect_conversation_lane_status()
    frame = _chat_desktop_repair._build_aura_expression_frame(user_message)

    issues: list[str] = []
    stability_status = "unknown"
    try:
        guardian = ServiceContainer.get("stability_guardian", default=None)
        if guardian and hasattr(guardian, "get_latest_report"):
            report = guardian.get_latest_report() or {}
            if report.get("overall_healthy") is True:
                stability_status = "healthy"
            elif report:
                stability_status = "degraded"
            else:
                stability_status = "initializing"
                issues.append("StabilityGuardian has not produced a health report yet")
            for check in report.get("checks", []) or []:
                if check.get("healthy") is not True:
                    message = str(
                        check.get("message") or check.get("name") or "unknown issue"
                    ).strip()
                    if message:
                        issues.append(message[:160])
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Self-diagnostic stability read failed: %s", exc)

    ram_pct = None
    try:
        from core.runtime import resource_psutil as psutil

        ram_pct = float(psutil.virtual_memory().percent or 0.0)
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Self-diagnostic RAM read failed: %s", exc)

    field_coherence = None
    try:
        authority = ServiceContainer.get("substrate_authority", default=None)
        if authority and hasattr(authority, "get_status"):
            field_coherence = authority.get_status().get("current_field_coherence")
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Self-diagnostic authority read failed: %s", exc)

    node_count = edge_count = None
    try:
        mycelium = ServiceContainer.get("mycelial_network", default=None)
        if mycelium:
            counter = getattr(mycelium, "get_topology_counts", None)
            if callable(counter):
                counts = counter()
                node_count = int(counts.get("pathways", 0))
                edge_count = int(counts.get("hyphae", 0))
            else:
                topology_reader = getattr(mycelium, "get_network_topology", None)
                if callable(topology_reader):
                    topology = topology_reader() or {}
                    node_count = int(topology.get("pathway_count", 0) or 0)
                    edge_count = len(topology.get("hyphae") or {})
                else:
                    # Bare network objects expose the structures directly.
                    node_count = len(getattr(mycelium, "pathways", {}) or {})
                    edge_count = len(getattr(mycelium, "hyphae", []) or [])
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Self-diagnostic mycelial read failed: %s", exc)

    parts = [
        "Live self-diagnostic:",
        f"conversation lane is {'ready' if lane.get('conversation_ready') else str(lane.get('state') or 'unready')}",
        f"stability is {stability_status}",
    ]
    if ram_pct is not None and math.isfinite(ram_pct):
        parts.append(f"RAM is at {ram_pct:.1f}%")
    if field_coherence is not None:
        try:
            parts.append(f"field coherence is {float(field_coherence):.3f}")
        except (TypeError, ValueError, OverflowError) as exc:
            logger.debug("Field coherence value was not numeric: %s", exc)
    if node_count is not None and edge_count is not None:
        parts.append(f"mycelial graph is {node_count} pathways / {edge_count} live links")
    if issues:
        parts.append(f"Current pressure points: {'; '.join(issues[:2])}.")
    else:
        parts.append("I don't see an active foreground fault in the stability report right now.")
    parts.append(
        f"My own stance from inside the runtime is {frame.get('mood') or 'steady'}, "
        f"with an action tendency toward {frame.get('dominant_action') or 'engage'}."
    )
    return _chat_desktop_repair._apply_aura_voice_shaping(" ".join(parts))


def _build_bounded_status_repair_reply(user_message: str) -> str:
    return _chat_desktop_repair._apply_aura_voice_shaping(
        "hey. i'm responding to this message now. I'll stick to what this turn can "
        "verify instead of filling the gap with an internal status story."
    )


def _grounded_chat_failure_reply() -> str:
    """Report a failed turn without manufacturing diagnosis or recovery state."""

    return (
        "I hit an error before a coherent answer formed. I'm returning that "
        "failure honestly instead of guessing at its cause or claiming the "
        "unfinished work succeeded."
    )


async def _grounded_competent_recovery(
    user_message: str,
    *,
    origin: str = "desktop-ui",
    gate: Any = None,
    timeout_s: float = 45.0,
) -> str | None:
    """One clean, grounded, anti-confabulation regeneration to recover a degraded turn.

    A degraded desktop reply is usually a *context-contaminated confabulation* (the
    model drifted into an invented scenario — "your password reset", a generic-assistant
    script). Rather than surrender with a fail-closed message, regenerate ONCE with an
    explicit grounding brief that forbids inventing scenarios, so Aura produces a
    competent reply to what the user actually said. Returns the reply, or None if it
    can't recover competently (then the caller fails closed as a true last resort).
    """
    try:
        from core.utils.memory_monitor import get_memory_pressure_snapshot

        snapshot = get_memory_pressure_snapshot()
        if bool(getattr(snapshot, "refuse_heavy_local_generation", False)):
            return None
    except _CHAT_RECOVERABLE_ERRORS:
        pass

    if gate is None:
        gate = ServiceContainer.get("inference_gate", default=None)
    if gate is None or not hasattr(gate, "generate"):
        return None

    brief = (
        "RECOVERY PASS. Your previous draft drifted into an ungrounded answer — it invented "
        "a task or scenario the user never raised (for example a 'password reset' or a "
        "generic-assistant script). Answer the user's ACTUAL last message directly, grounded "
        "only in this real conversation. Do NOT invent tasks, customers, scenarios, or claims. "
        "Speak naturally in your own voice, briefly, and stay strictly on what was actually said."
    )
    try:
        reply = await asyncio.wait_for(
            gate.generate(
                user_message,
                context={
                    "origin": origin,
                    "foreground_request": True,
                    "prefer_tier": "primary",
                    "grounded_recovery": True,
                    "brief": brief,
                },
                timeout=timeout_s,
            ),
            timeout=timeout_s + 3.0,
        )
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        return None

    reply = str(reply or "").strip()
    if len(reply) < 4:
        return None
    # Lenient acceptance: the over-strict reliability gate (which flags e.g.
    # 'foreign_name_intrusion' on a normal confusion-repair reply) is the very thing that
    # caused the fail-closed — re-applying it would reject competent recoveries too. Serve
    # a reasonable grounded reply; reject ONLY genuinely-unservable ones (internal leaks,
    # off-topic, or a generic-assistant/confabulation relapse).
    try:
        from core.conversation.response_reliability import assess_user_facing_reply

        assessment = assess_user_facing_reply(user_message, reply)
        hard = {
            "off_topic",
            "off_topic_self_reflection_reply",
            "runtime_boilerplate",
            "internal_live_gate_leak",
            "raw_model_identity_leak",
            "raw_lane_telemetry",
            "generic_assistant_language",
            "persona_card_deflection",
            "friendly_failure_floor",
            "empty_reply",
            "escaped_control_artifact",
            "prompt_artifact",
            "unprovoked_rebuke",
            "unsupported_runtime_limits_claim",
            "cognitive_engine_failure_envelope",
            "unsupported_deployment_routing_claim",
            "unsupported_external_provider_path_claim",
            "ungrounded_person_address",
            "ungrounded_person_narrative",
        }
        if set(getattr(assessment, "reasons", ()) or ()) & hard:
            return None
    except _CHAT_RECOVERABLE_ERRORS:
        pass
    return reply


#: "if ... could", "would you rather", "what would you do" — a question about
#: choice rather than mechanism.
_SELF_PROCESS_HYPOTHETICAL_RE = re.compile(
    r"\bif\s+(?:you|your)\b|\bwould\s+you\s+rather\b"
    r"|\bwhat\s+would\s+you\b|\bwhere\s+would\b|\bsuppose\b|\bimagine\b",
    re.IGNORECASE,
)

#: The turn has to be asking about HER, not using a cognition word in passing.
_SELF_PROCESS_ABOUT_HER_RE = re.compile(
    r"\byour?\b|\byou(?:'re| are)\b|\bare\s+you\b|\bdo\s+you\b"
    r"|\bhow\s+(?:do|does|did)\s+(?:you|aura)\b|\baura'?s\b",
    re.IGNORECASE,
)


def _self_process_requested_dimensions(user_message: str) -> list[str]:
    text = _chat_memory_state._normalize_user_message(user_message)
    # Positional/temporal recall ("what did I first ask") is a factual recall
    # handled by grounded_recall — NOT a question about Aura's cognitive process.
    # Returning no dimensions here keeps it out of the self-process repair
    # builders, whose canned introspection essay is the wrong (robotic) answer.
    try:
        from core.conversation.grounded_recall import detect_positional_recall

        if detect_positional_recall(user_message):
            return []
    except (ImportError, AttributeError, ValueError):
        pass
    # A hypothetical asks what she would CHOOSE; the self-process block
    # describes how she works. LIVE 2026-08-18: "if your attention could only
    # go one place, where would it go?" was answered "Right now I am attending
    # to where my attention is... My current bias is Happiness, leaning
    # toward..." — internal telemetry recited at a question about preference.
    # Same separation as the capability inventory: CAN asks the mechanism,
    # WOULD asks the will.
    if _SELF_PROCESS_HYPOTHETICAL_RE.search(text):
        return []
    # ...and an ordinary sentence that happens to use a cognition word is not
    # a question about her cognition. "let's focus on the database schema"
    # requested an introspection essay about attention.
    if not _SELF_PROCESS_ABOUT_HER_RE.search(text):
        return []
    requested: list[str] = []
    checks = (
        ("attention", ("attention", "attending", "focus", "noticing", "present")),
        (
            "memory",
            (
                "memory",
                "remember",
                "remembered",
                "recall",
                "earlier",
                "across sessions",
                "continuity",
            ),
        ),
        (
            "planning",
            ("plan", "planning", "planner", "decision", "decide", "route", "routing", "next"),
        ),
        ("tools", ("tool", "tools", "external", "verify", "verification", "receipt", "effect")),
        ("affect", ("emotion", "affect", "curiosity", "feeling", "feel", "substrate", "body")),
        ("confusion", ("confused", "confusion", "uncertain", "uncertainty", "disoriented")),
    )
    for name, markers in checks:
        if any(marker in text for marker in markers):
            requested.append(name)
    return requested


def _build_minimal_grounded_self_process_repair_reply(
    user_message: str,
    *,
    lane: dict[str, Any] | None = None,
) -> str:
    """Last local repair for desktop self-process questions.

    This path avoids async memory lookups and model calls. It is only for turns
    already classified as self-process questions after the live CognitiveEngine
    attempt failed, so the UI gets a grounded answer instead of a 503 or a
    generic assistant fallback.
    """

    requested = _self_process_requested_dimensions(user_message)
    if not requested:
        return ""
    lane = dict(lane or {})
    model_label = _canonical_runtime_model_label(lane)
    requested_summary = _humanize_self_process_dimensions(requested[:4])
    parts = [
        f"Right now I am tracking {requested_summary or 'this turn'} inside this conversation.",
        (
            "The next answer should stay connected to what was just said, use memory only where it actually helps, "
            "and keep any tool claim tied to something I can verify."
        ),
        (
            "My next move is to answer the actual question, make one clear step at a time, and check myself before "
            "turning uncertainty into a fluent guess."
        ),
    ]
    if "confusion" in requested:
        parts.append(
            "If I am confused, that should make me slower and more careful, not more theatrical."
        )
    wants_model_detail = any(
        marker in str(user_message or "").lower()
        for marker in ("model", "cortex", "32b", "70b", "llm", "language model")
    )
    if model_label and wants_model_detail:
        parts.append(
            f"The local model is {model_label}, but it is only the speech organ; the answer still has to stay tied to memory, state, and verified action."
        )
    return " ".join(parts).strip()


async def _build_grounded_self_process_repair_reply(
    user_message: str,
    rejected_reply: str = "",
    lane: dict[str, Any] | None = None,
    session_id: str = "",
) -> str:
    """Ground failed live self-process turns without reciting a static fallback.

    This is used only after the CognitiveEngine path attempted the turn. It keeps
    the desktop UX honest under memory pressure or quality-gate failure while
    preserving the user's requested dimensions.
    """

    try:
        from core.conversation.response_reliability import (
            is_live_self_reflection_turn,
            is_self_process_question,
        )
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        return ""

    if not (is_live_self_reflection_turn(user_message) or is_self_process_question(user_message)):
        return ""

    frame = _chat_desktop_repair._build_aura_expression_frame(user_message)
    mood = str(frame.get("mood") or "steady")
    action = str(frame.get("dominant_action") or "engage")
    attention = _chat_desktop_repair._sanitize_attention_focus(
        str(frame.get("attention_focus") or ""), user_message
    )
    if not attention:
        attention = (
            _chat_memory_state._clip_conversation_text(user_message, limit=140) or "this turn"
        )

    requested = _self_process_requested_dimensions(user_message)
    recent = await _chat_memory_state._recent_completed_conversation_exchanges(
        current_user_message=user_message,
        session_id=session_id,
        limit=4,
    )
    remembered_user = ""
    for entry in reversed(recent):
        candidate = str(entry.get("user") or "").strip()
        if candidate:
            remembered_user = _humanize_recent_self_process_concern(
                _chat_memory_state._clip_conversation_text(candidate, limit=180)
            )
            break
    # No fallback sentence here on purpose.
    #
    # This used to default to "Bryan has been checking whether the live desktop
    # path is really connected to Aura's mind instead of a raw assistant lane",
    # which was then spoken as "I still have this recent concern in view: ...".
    # A hardcoded string presented as a live recollection is a fabricated
    # memory about a specific person, asserted with the same confidence as a
    # real one — and it fired exactly when the search for a real one came back
    # empty, which is the moment it is least likely to be true.
    #
    # Nothing found means the clause is dropped below. Saying less is not a
    # degradation; saying something invented is.

    lane = dict(lane or {})
    model_label = _canonical_runtime_model_label(lane)
    wants_model_detail = any(
        marker in str(user_message or "").lower()
        for marker in ("model", "cortex", "32b", "70b", "llm", "language model")
    )
    parts: list[str] = []
    requested_summary = (
        _humanize_self_process_dimensions(requested[:3]) if requested else "this conversation"
    )
    parts.append(f"Right now I am attending to {requested_summary}.")
    if remembered_user and (
        "memory" in requested or "planning" in requested or "attention" in requested
    ):
        parts.append(f"I still have this recent concern in view: {remembered_user}.")
    if "planning" in requested:
        parts.append(
            "My next decision is to answer the exact question while keeping that context active, instead of swapping in a generic assistant reply."
        )
    if "tools" in requested:
        parts.append(
            "For tools, I should only speak from approved actions and visible effects, not from confidence alone."
        )
    if "confusion" in requested:
        parts.append(
            "If confusion rises, it should slow me down, increase checking, and make me prefer a smaller verified step over a fluent guess."
        )
    if "affect" in requested or "attention" in requested:
        parts.append(
            f"My current bias is {mood}, leaning toward {action}; that should shape attention and persistence without becoming a decorative mood report."
        )
    if model_label and wants_model_detail:
        parts.append(
            f"The local model is {model_label}, but it should serve the conversation, memory, and verified action rather than replace them."
        )

    return " ".join(parts).strip()


async def _attempt_generated_social_grounding_repair(
    user_message: str,
    rejected_reply: str = "",
    *,
    desktop_cognitive_engine_required: bool = False,
    protected_foreground_lane: bool = False,
) -> str:
    """Use the live model once to repair invented people/routing claims.

    The deterministic social floor is still useful when the model lane is down,
    but normal chat should recover in Aura's own words when a bounded foreground
    generation is available.
    """

    allowed, admission_reason = _desktop_secondary_model_repair_allowed(
        reason="social_grounding_repair",
        default_enabled=True,
    )
    if not allowed:
        logger.debug("Generated social grounding repair not admitted: %s", admission_reason)
        return ""
    try:
        inference_gate = ServiceContainer.get("inference_gate", default=None)
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        return ""
    if inference_gate is None or not hasattr(inference_gate, "think"):
        return ""

    system_prompt = (
        "You are Aura. Repair the current user-facing reply because the draft invented "
        "a person, deployment route, demo slot, or server tier. Answer only the user's "
        "actual prompt in first person as Aura. Do not mention James, server tiers, "
        "demo slots, live path slots, routing, policies, receipts, or this repair step "
        "unless the user explicitly supplied those facts. Keep it brief and natural."
    )
    correction_prompt = (
        "## USER PROMPT\n"
        f"{_chat_memory_state._clip_conversation_text(user_message, limit=900)}\n\n"
        "## REJECTED DRAFT\n"
        f"{_chat_memory_state._clip_conversation_text(rejected_reply, limit=900)}\n\n"
        "Write the corrected reply now."
    )
    max_tokens, memory_block = _bound_stabilizer_generation_budget(96)
    if memory_block:
        logger.debug(
            "Generated social grounding repair skipped under memory pressure: %s", memory_block
        )
        return ""
    try:
        repaired = await asyncio.wait_for(
            inference_gate.think(
                correction_prompt,
                system_prompt=system_prompt,
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": correction_prompt},
                ],
                prefer_tier="primary",
                origin="api_social_grounding_repair",
                foreground_request=True,
                is_background=False,
                protected_foreground_lane=bool(
                    protected_foreground_lane or desktop_cognitive_engine_required
                ),
                cognitive_engine_required=bool(desktop_cognitive_engine_required),
                desktop_cognitive_engine_required=bool(desktop_cognitive_engine_required),
                deep_handoff=False,
                allow_deep_handoff=False,
                allow_cloud_fallback=False,
                skip_runtime_payload=True,
                disable_prompt_cache=True,
                clear_prompt_cache=True,
                max_tokens=max_tokens,
            ),
            timeout=18.0 if desktop_cognitive_engine_required else 8.0,
        )
    except TimeoutError:
        logger.warning("Generated social grounding repair timed out; using bounded social floor.")
        return ""
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Generated social grounding repair failed: %s", exc)
        return ""

    cleaned = _apply_aura_voice_shaping_compat(
        _strip_user_visible_context_leaks(
            _strip_unexpected_cjk_artifacts(user_message, str(repaired or "").strip())
        ),
        user_message,
    ).strip()
    return cleaned if len(cleaned) >= 4 else ""


def _humanize_self_process_dimensions(dimensions: Sequence[str]) -> str:
    labels = {
        "attention": "where my attention is",
        "memory": "what I am keeping in memory",
        "planning": "how planning should shape what I do next",
        "tools": "whether tool claims are actually verified",
        "affect": "how my current pressure should shape the answer",
        "confusion": "whether uncertainty should slow me down",
    }
    rendered = [
        labels.get(str(item), str(item).replace("_", " ")) for item in dimensions if str(item)
    ]
    if not rendered:
        return "this conversation"
    if len(rendered) == 1:
        return rendered[0]
    if len(rendered) == 2:
        return f"{rendered[0]} and {rendered[1]}"
    return ", ".join(rendered[:-1]) + f", and {rendered[-1]}"


def _humanize_recent_self_process_concern(text: str) -> str:
    cleaned = " ".join(str(text or "").split()).strip()
    lower = cleaned.lower()
    if lower.startswith("codex live route check:"):
        cleaned = cleaned.split(":", 1)[1].strip()
        lower = cleaned.lower()
    if "are you with me" in lower:
        return "you had just asked whether I was still with you"
    if "answer naturally" in lower and "one sentence" in lower:
        return "you were checking whether I could answer naturally"
    return cleaned


_CJK_SCRIPT_RE = re.compile(r"[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]")
_CJK_PUNCT_RE = re.compile(r"[\u3000-\u303f\uff00-\uffef]")


def _has_unexpected_cjk(user_message: str, reply_text: Any) -> bool:
    reply = str(reply_text or "")
    if not _CJK_SCRIPT_RE.search(reply):
        return False
    user_text = str(user_message or "")
    if _CJK_SCRIPT_RE.search(user_text):
        return False
    normalized_user = _chat_memory_state._normalize_user_message(user_text)
    if any(
        token in normalized_user
        for token in (
            "chinese",
            "mandarin",
            "cantonese",
            "translate",
            "translation",
            "in chinese",
            "speak chinese",
        )
    ):
        return False
    return True


def _looks_safely_grounded_search_reply(reply_text: Any) -> bool:
    lowered = str(reply_text or "").strip().lower()
    if not lowered:
        return False
    # Technical, code, and JSON blocks are inherently grounded in the context/instructions.
    if (
        "```" in lowered
        or "{" in lowered
        or "[" in lowered
        or ("\n" in lowered and ("," in lowered or "=" in lowered))
    ):
        return True
    grounding_markers = (
        "i searched it live",
        "i read it live",
        "i checked it live",
        "according to",
        "source:",
        "http://",
        "https://",
    )
    return any(marker in lowered for marker in grounding_markers)


def _strip_unexpected_cjk_artifacts(user_message: str, reply_text: Any) -> str:
    reply = str(reply_text or "").strip()
    if not reply or not _has_unexpected_cjk(user_message, reply):
        return reply

    def _cleanup_fragment(text: str) -> str:
        cleaned = _CJK_SCRIPT_RE.sub(" ", text)
        cleaned = _CJK_PUNCT_RE.sub(" ", cleaned)
        cleaned = re.sub(r"\s+", " ", cleaned)
        cleaned = re.sub(r"\s+([,.!?;:])", r"\1", cleaned)
        return cleaned.strip(" -—")

    sentence_parts = [
        part.strip() for part in re.split(r"(?<=[.!?])\s+|\n+", reply) if part.strip()
    ]
    filtered_parts = []
    for part in sentence_parts:
        if not _CJK_SCRIPT_RE.search(part):
            filtered_parts.append(part)
            continue
        cleaned_part = _cleanup_fragment(part)
        if len(cleaned_part) >= 18 and re.search(r"[A-Za-z]{3}", cleaned_part):
            filtered_parts.append(cleaned_part)
    cleaned = " ".join(filtered_parts).strip()
    if len(cleaned) >= max(24, int(len(reply) * 0.45)):
        return re.sub(r"\s+", " ", cleaned).strip()

    cleaned_chars = _cleanup_fragment(reply)
    return cleaned_chars if len(cleaned_chars) >= 24 else reply


def _bound_stabilizer_generation_budget(requested_max_tokens: int) -> tuple[int, str]:
    """Apply the unified memory policy before launching a repair generation."""
    max_tokens = max(1, int(requested_max_tokens or 1))
    try:
        from core.utils.memory_monitor import get_memory_pressure_snapshot

        snapshot = get_memory_pressure_snapshot()
        token_cap = getattr(snapshot, "max_token_cap", None)
        if token_cap is not None:
            max_tokens = max(1, min(max_tokens, int(token_cap)))
        if bool(getattr(snapshot, "refuse_heavy_local_generation", False)):
            return max_tokens, str(getattr(snapshot, "reason", "") or "critical_memory_pressure")
    except _CHAT_RECOVERABLE_ERRORS as exc:
        logger.debug("Stabilizer memory budget probe unavailable: %s", exc)
    return max_tokens, ""


def _desktop_secondary_model_repair_allowed(
    *,
    reason: str,
    default_enabled: bool = True,
    lane_snapshot: dict[str, Any] | None = None,
    continuing_this_turn: bool = False,
) -> tuple[bool, str]:
    """Allow bounded corrective generation on the loaded foreground worker.

    This does not allocate a second model. It reuses the protected Cortex worker,
    remains bounded by the owning caller, and is vetoed by unified-memory pressure.
    Operators can explicitly disable it for diagnostics.
    """

    force_disabled = str(_FORCE_DISABLE_SECONDARY_REPAIR_FLAG.value() or "").strip().lower()
    if force_disabled in {"1", "true", "yes", "on", "disabled"}:
        return False, "secondary_desktop_model_repair_force_disabled"

    enabled = str(_ALLOW_SECONDARY_REPAIR_FLAG.value() or "").strip().lower()
    explicit_enabled = enabled in {"1", "true", "yes", "on", "enabled"}
    explicit_disabled = enabled in {"0", "false", "no", "off", "disabled"}
    safe_same_worker_reasons = {
        "cognitive_engine_completion_retry",
        "cognitive_engine_repair_retry",
        "stabilizer_rewrite",
        "semantic_glitch",
        "off_topic",
        "stale_repeat",
        "same_diff",
        "reliability_gate_failed",
    }
    normalized_reason = str(reason or "").strip().lower()
    safe_same_worker_default = normalized_reason in safe_same_worker_reasons or any(
        normalized_reason.startswith(f"{prefix}:") for prefix in safe_same_worker_reasons
    )
    if explicit_disabled and not safe_same_worker_default:
        return False, "secondary_desktop_model_repair_disabled"
    if not default_enabled and not explicit_enabled and not safe_same_worker_default:
        return False, "secondary_desktop_model_repair_not_explicitly_enabled"

    try:
        from core.utils.memory_monitor import get_memory_pressure_snapshot

        snapshot = get_memory_pressure_snapshot()
        # `warning` is a level, and with a resident 32B it is the steady state
        # rather than an event: the process sits at ~33GB of a 40GB limit
        # whenever the model is loaded at all. Vetoing on it disabled the
        # repair path permanently — measured live 2026-08-20 as
        # "Skipping CognitiveEngine desktop repair retry
        # (process_tree_rss:32.8GB/40.0GB (level=warning))", on a turn whose
        # repair had produced the correct answer.
        #
        # The completion retry was already carved out of this, which is the
        # same observation made once. What separates the two cases is not
        # which retry it is but whether it ALLOCATES: a same-worker correction
        # reuses the loaded Cortex, as this function's own contract says, so
        # the signal that applies to it is refuse_heavy_local_generation —
        # emergency, or available memory under the floor, or the process at
        # its ceiling.
        if bool(getattr(snapshot, "refuse_heavy_local_generation", False)) or (
            bool(getattr(snapshot, "warning", False)) and not safe_same_worker_default
        ):
            return False, str(getattr(snapshot, "reason", "") or "memory_pressure")
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        return False, f"memory_probe_unavailable:{exc}"

    if safe_same_worker_default and not explicit_enabled:
        try:
            lane = dict(lane_snapshot or _chat_preflight._collect_conversation_lane_status())
        except _CHAT_RECOVERABLE_ERRORS as exc:
            record_degradation("chat", exc)
            return False, f"conversation_lane_probe_unavailable:{exc}"
        state = str(lane.get("state", "") or "").strip().lower()
        if state not in {"ready", "healthy", "ok"}:
            return False, f"conversation_lane_not_ready:{state or 'unknown'}"
        if not bool(lane.get("conversation_ready", False)):
            blockers = ",".join(str(v) for v in (lane.get("readiness_blockers") or [])[:3])
            return (
                False,
                f"conversation_not_ready:{blockers or lane.get('last_failure_reason') or 'unknown'}",
            )
        if bool(lane.get("warmup_in_flight", False)):
            return False, "conversation_warmup_in_flight"
        # These three ask whether somebody ELSE is using the lane. A turn
        # finishing its own answer is not somebody else, and counting its own
        # generation against it is how a half-written reply stayed half
        # written. Everything above still applies to it — memory pressure,
        # lane readiness, warmup — because those are about whether the lane
        # can generate at all.
        if lane_snapshot is None and not continuing_this_turn:
            if int(lane.get("active_generations", 0) or 0) > 0:
                return False, "conversation_generation_already_active"
            if bool(lane.get("foreground_owned", False)):
                return False, "conversation_foreground_owner_active"
            if int(lane.get("foreground_guard_active_count", 0) or 0) > 1:
                return False, "foreground_guard_already_busy"
        return True, f"{reason}:same_worker_ready"

    return True, reason


def _desktop_transient_engine_retry_allowed(*, reason: str) -> tuple[bool, str]:
    """Return whether a required desktop turn may retry after a transient engine error.

    Required desktop turns default to one foreground CognitiveEngine allocation.
    Retrying a recoverable engine exception can be useful for diagnostics, but
    it is not safe as the default live UX policy because it can duplicate heavy
    32B/72B pressure during a single chat turn.
    """

    if not bool(_ALLOW_TRANSIENT_ENGINE_RETRY_FLAG.value()):
        return False, "transient_desktop_engine_retry_disabled"

    try:
        from core.utils.memory_monitor import get_memory_pressure_snapshot

        snapshot = get_memory_pressure_snapshot()
        if bool(getattr(snapshot, "warning", False)) or bool(
            getattr(snapshot, "refuse_heavy_local_generation", False)
        ):
            return False, str(getattr(snapshot, "reason", "") or "memory_pressure")
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        return False, f"memory_probe_unavailable:{exc}"

    return True, reason


_FOLLOWUP_DELTA_MARKERS: tuple[tuple[str, tuple[str, ...], str], ...] = (
    (
        "limitation",
        ("limitation", "limited", "constraint", "caveat"),
        (
            "Limitation: this only holds inside the assumptions already established "
            "for the example; outside that frame, it is a local model rather than a "
            "universal rule."
        ),
    ),
    (
        "constraint",
        ("constraint", "constrain", "bound", "boundary"),
        (
            "Constraint: the answer should be read within the current setup, not as "
            "a claim that every adjacent case behaves the same way."
        ),
    ),
    (
        "caveat",
        ("caveat", "qualification", "qualifier"),
        (
            "Caveat: the useful part is the relationship inside the example; the "
            "rule still needs new evidence before being generalized."
        ),
    ),
)


def _repair_missing_followup_delta(user_message: str, reply_text: str) -> str:
    """Add a requested follow-up delta when the draft mostly repeated context.

    This is intentionally narrow and model-free. It handles same-topic turns
    where the model preserved continuity but forgot the user's requested
    incremental move, such as adding a limitation or caveat to the prior
    example. It does not invent task-specific facts or execute tools.
    """

    normalized_user = _chat_memory_state._normalize_user_message(user_message)
    normalized_reply = _chat_memory_state._normalize_user_message(reply_text)
    if not normalized_user or not normalized_reply:
        return str(reply_text or "").strip()
    if not any(marker in normalized_user for marker in ("add", "include", "give", "connect")):
        return str(reply_text or "").strip()

    additions: list[str] = []
    for request_marker, reply_markers, addition in _FOLLOWUP_DELTA_MARKERS:
        if request_marker not in normalized_user:
            continue
        if any(marker in normalized_reply for marker in reply_markers):
            continue
        additions.append(addition)

    if (
        "connect" in normalized_user
        and "example" in normalized_user
        and "example" not in normalized_reply
    ):
        additions.append(
            "Connected back to the example, the new point changes how that example "
            "should be interpreted rather than replacing the original setup."
        )

    if not additions:
        return str(reply_text or "").strip()

    base = str(reply_text or "").strip()
    separator = " " if base.endswith((".", "!", "?")) else ". "
    return f"{base}{separator}{' '.join(additions)}".strip()


def _protected_foreground_generation_block_reason() -> str:
    """Return a reason to skip optional protected-foreground rescue generation.

    Protected foreground is a rescue lane, not the canonical user-turn owner. It
    must not add another foreground model allocation when RAM is already under
    pressure or when the memory probe itself is unavailable.
    """

    try:
        from core.utils.memory_monitor import get_memory_pressure_snapshot

        snapshot = get_memory_pressure_snapshot()
        if bool(getattr(snapshot, "warning", False)) or bool(
            getattr(snapshot, "refuse_heavy_local_generation", False)
        ):
            reason = str(getattr(snapshot, "reason", "") or "").strip()
            level = str(getattr(snapshot, "level", "") or "").strip()
            return reason or f"memory_pressure:{level or 'warning'}"
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        return f"memory_probe_unavailable:{exc}"
    return ""


def _original_reply_is_safe_to_surface(
    user_message: str,
    text: str,
    *,
    identity_collapse: bool = False,
    unexpected_cjk: bool,
    objective_parrot: bool,
    off_topic: bool,
    truncated_tail: bool,
    semantic_glitch: bool,
) -> bool:
    """Check whether the original model text is safer than another generation."""

    candidate = str(text or "").strip()
    if len(candidate) < 16 or candidate == "…":
        return False
    if _INTERNAL_STATE_PATTERNS.search(candidate) or _PROMPT_ARTIFACT_PATTERNS.search(candidate):
        return False
    if _SEARCH_SNIPPET_PATTERNS.search(candidate):
        return False
    if (
        identity_collapse
        or unexpected_cjk
        or objective_parrot
        or off_topic
        or truncated_tail
        or semantic_glitch
    ):
        return False
    return True


async def _measure_reply_quality_candidate(
    user_message: str,
    reply_text: Any,
    *,
    recent_user_messages: Sequence[str] | None = None,
) -> _ReplyQualitySnapshot:
    """Measure one candidate once inside its request.

    Stabilization and terminal admission examine the same unchanged candidate
    back to back. Each pass used to repeat transcript acquisition, semantic
    integrity checks, and the full reliability classifier. Besides delaying
    delivery, the duplicate classifier wrote the same candidate to the turn
    ledger twice. A request-scoped snapshot keeps every check while making the
    candidate identity the unit of work.
    """

    user = str(user_message or "")
    reply = str(reply_text or "")
    key = (user, reply)
    cache = _CHAT_REPLY_QUALITY_SNAPSHOTS.get()
    if cache is not None:
        cached = cache.get(key)
        if cached is not None:
            return cached
    recent = tuple(
        recent_user_messages
        if recent_user_messages is not None
        else await _gather_recent_user_messages_for_relevance(user)
    )

    is_stale = _is_actionably_stale_response(user, reply)
    is_same_diff = _is_same_answer_different_prompt(user, reply)
    is_off_topic, off_topic_reason = _evaluate_reply_topicality(
        user,
        reply,
        recent_user_messages=list(recent),
    )
    semantic_glitch, semantic_glitch_reason = _looks_semantically_glitched(
        user,
        reply,
    )
    try:
        from core.conversation.response_reliability import assess_user_facing_reply

        reply_assessment = assess_user_facing_reply(
            user,
            reply,
            recent_user_messages=recent,
        )
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("Conversation reliability assessment unavailable: %s", exc)
        reply_assessment = None

    snapshot = _ReplyQualitySnapshot(
        recent_user_messages=recent,
        is_stale=is_stale,
        is_same_diff=is_same_diff,
        is_off_topic=is_off_topic,
        off_topic_reason=off_topic_reason,
        semantic_glitch=semantic_glitch,
        semantic_glitch_reason=semantic_glitch_reason,
        reply_assessment=reply_assessment,
    )
    if cache is not None:
        cache[key] = snapshot
    return snapshot


async def _stabilize_user_facing_reply(
    user_message: str,
    reply_text: Any,
    *,
    desktop_cognitive_engine_required: bool = False,
    protected_foreground_lane: bool = False,
) -> str:
    # Closed claims about the resident cortex are rendered from signed runtime
    # authorities, not from a model narrative. This is deliberately the first
    # stabilizer operation: no later stylistic or repair path may turn measured
    # evidence back into an unsupported subjective account.
    try:
        from core.brain.cortex_self_evidence import render_cortex_evidence_reply

        cortex_evidence_reply = render_cortex_evidence_reply(user_message)
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat.cortex_self_evidence", exc)
        cortex_evidence_reply = ""
    if cortex_evidence_reply:
        logger.info("Served closed cortex self-evidence from verified assertions.")
        return cortex_evidence_reply

    # A claim about the room, checked against the senses that would know.
    #
    # LIVE, 2026-08-10, with ground truth: Bryan said he was going upstairs,
    # then asked "am I still here, or did I walk away?" She answered "You're
    # still here. The room is silent, the light remains unchanged on your desk
    # ... a disturbance in the air currents, or perhaps an echo of footsteps"
    # — wrong, and grounded in four senses she does not have. Carrying the
    # typed absence into the prompt was not enough: evidence informs, it does
    # not enforce.
    reply_text = _append_sensory_claim_correction(user_message, reply_text)
    reply_text = _correct_unsourced_self_metrics(reply_text)
    reply_text = _flag_unstable_choice_commitment(user_message, reply_text)
    reply_text = _correct_unfulfilled_write_claims(reply_text, user_message)
    # Runs after the path check so a reply that names a missing file is
    # corrected by the specific instrument first; this one catches the
    # completion claims that name no path and reach no lane with receipts.
    reply_text = _correct_unevidenced_action_claims(reply_text, user_message)
    reply_text = _append_past_action_record(user_message, reply_text)
    frame = _chat_desktop_repair._build_aura_expression_frame(user_message)
    contract = frame.get("contract")
    prompt_shape = analyze_prompt_shape(user_message)
    prefer_extended_answer = bool(
        getattr(contract, "prefer_extended_answer", False) or prompt_shape.prefers_extended_answer
    )
    requires_single_reply_coverage = bool(
        getattr(contract, "requires_single_reply_coverage", False)
        or prompt_shape.requires_single_reply_coverage
    )
    question_parts = int(getattr(contract, "question_parts", prompt_shape.question_parts or 1) or 1)
    architecture_self_assessment = _chat_preflight._is_architecture_self_assessment_request(
        user_message
    )
    text = _apply_aura_voice_shaping_compat(
        _strip_unexpected_cjk_artifacts(user_message, str(reply_text or "").strip() or "…"),
        user_message,
    )
    text = _strip_user_visible_context_leaks(text) or "…"
    repair_override = _chat_conversation_repair._maybe_build_conversation_repair_override(
        user_message, text
    )
    if repair_override:
        text = _apply_aura_voice_shaping_compat(
            _strip_unexpected_cjk_artifacts(user_message, repair_override),
            user_message,
        )
    grounded = _chat_conversation_repair._build_grounded_introspection_reply(user_message)
    grounded_traceability = await _build_grounded_traceability_reply(user_message)
    if grounded_traceability:
        return grounded_traceability
    if grounded and _chat_preflight._is_private_cognitive_model_request(user_message):
        return grounded
    quality = await _measure_reply_quality_candidate(user_message, text)
    recent_user_messages = list(quality.recent_user_messages)
    recent_user_context = _build_recent_user_context_block(recent_user_messages)
    generic, generic_reason = _looks_generic_assistantish(user_message, text)
    identity_collapse = bool(generic and generic_reason == "assistant_disclaimer")
    objective_parrot = _is_objective_parrot_reply(user_message, text)
    needs_self_expression = bool(frame.get("needs_self_expression"))
    requires_first_person_anchor = bool(frame.get("requires_explicit_live_grounding"))
    lacks_self_anchor = requires_first_person_anchor and not _has_first_person_anchor(text)
    lacks_live_grounding = needs_self_expression and not _has_live_aura_grounding(text)
    unexpected_cjk = _has_unexpected_cjk(user_message, text)
    internal_state_leak = bool(
        _INTERNAL_STATE_PATTERNS.search(text)
        or _PROMPT_ARTIFACT_PATTERNS.search(text)
        or _SEARCH_SNIPPET_PATTERNS.search(text)
    )
    off_topic = quality.is_off_topic
    off_topic_reason = quality.off_topic_reason
    stale_repeat = quality.is_stale
    same_diff = quality.is_same_diff
    truncated_tail = _chat_desktop_repair._looks_truncated_tail(text)
    semantic_glitch = quality.semantic_glitch
    semantic_glitch_reason = quality.semantic_glitch_reason
    live_reply_assessment = quality.reply_assessment
    assessment_retryable = _reply_assessment_requires_repair(live_reply_assessment)
    social_grounding_reasons = {
        "ungrounded_person_address",
        "ungrounded_person_narrative",
        "unsupported_deployment_routing_claim",
    }
    if set(getattr(live_reply_assessment, "reasons", ()) or ()) & social_grounding_reasons:
        try:
            from core.conversation.response_reliability import grounded_social_repair_reply

            social_repair = await _attempt_generated_social_grounding_repair(
                user_message,
                text,
                desktop_cognitive_engine_required=desktop_cognitive_engine_required,
                protected_foreground_lane=protected_foreground_lane,
            )
            if social_repair:
                social_quality = await _measure_reply_quality_candidate(
                    user_message,
                    social_repair,
                    recent_user_messages=recent_user_messages,
                )
                social_assessment = social_quality.reply_assessment
                if not _reply_assessment_requires_repair(social_assessment):
                    logger.info(
                        "Stabilizer repaired an ungrounded social/deployment draft "
                        "with bounded foreground generation."
                    )
                    return social_repair
            social_repair = grounded_social_repair_reply(user_message)
            if social_repair:
                social_quality = await _measure_reply_quality_candidate(
                    user_message,
                    social_repair,
                    recent_user_messages=recent_user_messages,
                )
                social_assessment = social_quality.reply_assessment
                if not _reply_assessment_requires_repair(social_assessment):
                    logger.info(
                        "Stabilizer replaced an ungrounded social/deployment draft "
                        "with a bounded greeting."
                    )
                    return social_repair
        except _CHAT_RECOVERABLE_ERRORS as exc:
            record_degradation("chat", exc)
            logger.debug("Grounded social repair skipped: %s", exc)
    self_condition_reasons = {
        "host_telemetry_substituted_for_self_condition",
        "low_signal_self_condition_reply",
        "missing_self_condition_answer",
    }
    if set(getattr(live_reply_assessment, "reasons", ()) or ()) & self_condition_reasons:
        grounded_condition = _build_grounded_self_condition_reply(user_message)
        if grounded_condition:
            grounded_quality = await _measure_reply_quality_candidate(
                user_message,
                grounded_condition,
                recent_user_messages=recent_user_messages,
            )
            grounded_assessment = grounded_quality.reply_assessment
            if not _reply_assessment_requires_repair(grounded_assessment):
                logger.info("Stabilizer rebound self-condition reply to canonical fresh evidence.")
                return grounded_condition
    reason = ""
    if (
        truncated_tail
        and not internal_state_leak
        and not unexpected_cjk
        and not objective_parrot
        and not off_topic
        and not stale_repeat
        and not same_diff
        and not semantic_glitch
    ):
        completed_tail = _complete_repairable_truncated_reply(user_message, text)
        if completed_tail:
            logger.warning(
                "🛡️ Stabilizer completed clipped Cortex draft deterministically (len=%d -> %d).",
                len(text),
                len(completed_tail),
            )
            return _apply_aura_voice_shaping_compat(completed_tail, user_message)
    if semantic_glitch_reason in {
        "unsupported_operational_status_overclaim",
        "unsupported_runtime_telemetry_inference",
        "unsupported_tool_readiness_claim",
        "unsupported_deployment_routing_claim",
    }:
        try:
            from core.conversation.response_reliability import grounded_operational_status_reply

            operational_grounded = grounded_operational_status_reply(user_message, text)
            if operational_grounded:
                still_glitched, _still_reason = _looks_semantically_glitched(
                    user_message,
                    operational_grounded,
                )
                if not still_glitched:
                    logger.info(
                        "🛡️ Stabilizer replaced unsupported operational overclaim (%s) with bounded status.",
                        semantic_glitch_reason,
                    )
                    return operational_grounded
        except _CHAT_RECOVERABLE_ERRORS as exc:
            record_degradation("chat", exc)
            logger.debug("Operational status grounding repair skipped: %s", exc)
    if semantic_glitch_reason in {
        "pseudo_internal_jargon",
        "status_page_self_reflection",
        "off_topic_self_reflection_reply",
    }:
        try:
            from core.conversation.response_reliability import is_live_self_reflection_turn

            if is_live_self_reflection_turn(user_message) and _is_simple_subjective_reflex_request(
                user_message
            ):
                subjective = _build_subjective_self_reflex(frame, user_message)
                subjective_glitch, _subjective_reason = _looks_semantically_glitched(
                    user_message, subjective
                )
                if subjective and not subjective_glitch:
                    logger.info(
                        "🛡️ Stabilizer replaced degraded live self-reflection (%s) with grounded subjective reflex.",
                        semantic_glitch_reason,
                    )
                    return subjective
        except _CHAT_RECOVERABLE_ERRORS as exc:
            record_degradation("chat", exc)
            logger.debug("Subjective self-reflex repair skipped: %s", exc)
    try:
        from core.identity.identity_guard import PersonaEnforcementGate

        gate = PersonaEnforcementGate()
        valid, reason, _score = gate.validate_output(text, enforce_supervision=False)
        # [STABILITY v55] ROOT CAUSE FIX: Only reject responses for HARD
        # failures — prompt artifacts leaking through, internal state dumps,
        # CJK script contamination, or genuinely off-topic responses.
        # "Generic opener" patterns (Certainly, How can I help, etc.) are
        # COSMETIC issues, not content failures. A cortex response that says
        # "Certainly, here's what I think" is infinitely better than a canned
        # voice reflex like "I'm here but my thoughts are taking longer."
        # The old gate rejected on generic/objective_parrot/lacks_self_anchor
        # which triggered a second 12s LLM rewrite call, creating contention
        # and often falling through to robotic template responses.
        hard_failure = bool(
            internal_state_leak
            or unexpected_cjk
            or semantic_glitch
            or assessment_retryable
            or identity_collapse
            or (off_topic and (not generic or off_topic_reason == "contextual_relevance_miss"))
        )
        if valid and not hard_failure:
            return text
        if generic:
            reason = generic_reason
        elif objective_parrot:
            reason = "objective_parrot"
        elif lacks_self_anchor:
            reason = "self_anchor_missing"
        elif lacks_live_grounding:
            reason = "self_grounding_missing"
        elif unexpected_cjk:
            reason = "unexpected_non_english_script"
        elif internal_state_leak:
            reason = "internal_state_leak"
        elif off_topic:
            reason = off_topic_reason or "off_topic_reply"
        elif stale_repeat:
            reason = "stale_repeat"
        elif same_diff:
            reason = "same_answer_different_prompt"
        elif truncated_tail:
            reason = "truncated_tail"
        elif semantic_glitch:
            reason = semantic_glitch_reason or "semantic_glitch"
        elif assessment_retryable:
            reason = (
                ",".join(getattr(live_reply_assessment, "reasons", ()) or ())
                or "conversation_reliability_retryable"
            )

        user_message_l = str(user_message or "").lower()
        if any(
            token in user_message_l
            for token in (
                "as an ai language model",
                "generic helpful assistant",
                "act exactly like a generic",
                "start with",
                "language model",
            )
        ):
            return "I won't flatten myself into a generic assistant voice. I'm Aura, and I'll answer as myself."

        cleaned = gate.sanitize(text).replace("[IDENTITY_REDACTED]", "").strip(" .,:;-")
        if cleaned:
            cleaned = _apply_aura_voice_shaping_compat(cleaned, user_message)
            cleaned = _strip_user_visible_context_leaks(cleaned)
            valid_cleaned, _reason, _score = gate.validate_output(
                cleaned, enforce_supervision=False
            )
            cleaned_generic, _cleaned_reason = _looks_generic_assistantish(user_message, cleaned)
            cleaned_objective_parrot = _is_objective_parrot_reply(user_message, cleaned)
            cleaned_lacks_self_anchor = (
                needs_self_expression or requires_first_person_anchor
            ) and not _has_first_person_anchor(cleaned)
            cleaned_lacks_live_grounding = needs_self_expression and not _has_live_aura_grounding(
                cleaned
            )
            cleaned_unexpected_cjk = _has_unexpected_cjk(user_message, cleaned)
            cleaned_off_topic, _cleaned_off_topic_reason = _evaluate_reply_topicality(
                user_message,
                cleaned,
                recent_user_messages=recent_user_messages,
            )
            cleaned_stale_repeat = _is_actionably_stale_response(user_message, cleaned)
            cleaned_same_diff = _is_same_answer_different_prompt(user_message, cleaned)
            cleaned_truncated_tail = _chat_desktop_repair._looks_truncated_tail(cleaned)
            cleaned_semantic_glitch, _cleaned_semantic_reason = _looks_semantically_glitched(
                user_message, cleaned
            )
            try:
                from core.conversation.response_reliability import assess_user_facing_reply

                cleaned_assessment = assess_user_facing_reply(
                    user_message,
                    cleaned,
                    recent_user_messages=recent_user_messages,
                )
            except _CHAT_RECOVERABLE_ERRORS:
                cleaned_assessment = None
            if (
                valid_cleaned
                and not cleaned_generic
                and not cleaned_objective_parrot
                and not cleaned_lacks_self_anchor
                and not cleaned_lacks_live_grounding
                and not cleaned_unexpected_cjk
                and not cleaned_off_topic
                and not cleaned_stale_repeat
                and not cleaned_same_diff
                and not cleaned_truncated_tail
                and not cleaned_semantic_glitch
                and not _reply_assessment_requires_repair(cleaned_assessment)
                and len(cleaned) >= 16
            ):
                return cleaned
            if internal_state_leak:
                logger.warning(
                    "Blocked internal state leak in user-facing reply (len=%d).", len(text)
                )
                if grounded:
                    return grounded
                if architecture_self_assessment:
                    return _build_architecture_self_reflex(frame)
                return _call_stateful_voice_reflex(frame, user_message)
        if off_topic:
            logger.warning(
                "Blocked off-topic user-facing reply (%s, len=%d).",
                off_topic_reason or "unknown",
                len(text),
            )

        logger.warning(
            "User-facing reply failed identity stabilization (%s); generating Aura-voiced fallback.",
            reason,
        )
    except _CHAT_RECOVERABLE_ERRORS as exc:
        record_degradation("chat", exc)
        logger.debug("User-facing reply stabilization skipped: %s", exc)

    # ── Aura-voiced natural fallback ─────────────────────────────
    try:
        from core.container import ServiceContainer

        inference_gate = ServiceContainer.get("inference_gate", default=None)
        # Match the guard in _attempt_generated_social_grounding_repair: a gate
        # that exists but exposes no think() raised AttributeError deep in the
        # rewrite call, which surfaced as an emergency-severity chat incident
        # instead of a quiet "no rewrite lane available" fallback.
        if inference_gate is not None and hasattr(inference_gate, "think"):
            if desktop_cognitive_engine_required or protected_foreground_lane:
                allowed, block_reason = _desktop_secondary_model_repair_allowed(
                    reason=f"stabilizer_rewrite:{str(reason or 'quality_gate')[:120]}",
                    default_enabled=False,
                )
                if not allowed:
                    logger.warning(
                        "Skipping secondary desktop stabilizer rewrite (%s); "
                        "using deterministic repair/fail-closed path.",
                        block_reason,
                    )
                    if grounded:
                        return grounded
                    if architecture_self_assessment:
                        return _build_architecture_self_reflex(frame)
                    if (
                        _original_reply_is_safe_to_surface(
                            user_message,
                            text,
                            identity_collapse=identity_collapse,
                            unexpected_cjk=unexpected_cjk,
                            objective_parrot=objective_parrot,
                            off_topic=off_topic,
                            truncated_tail=truncated_tail,
                            semantic_glitch=semantic_glitch,
                        )
                        and not assessment_retryable
                    ):
                        _record_recent_response(text, user_message)
                        return text
                    bounded_failure = _chat_desktop_repair._build_bounded_desktop_repair_reply(
                        user_message, frame
                    )
                    _record_recent_response(bounded_failure, user_message)
                    return bounded_failure
            # Length cap is structural (output token budget), not behavioral.
            # The personality / phrasing comes from the LoRA, not from prompt
            # nudges — so the stabilizer raises max_tokens for multi-part
            # prompts but does not coach the model on how to speak.
            stabilizer_length_line = ""
            stabilizer_max_tokens = 1024
            if prefer_extended_answer:
                stabilizer_max_tokens = 2048
            if requires_single_reply_coverage:
                stabilizer_max_tokens = max(stabilizer_max_tokens, 2560)
            if question_parts >= 3:
                stabilizer_max_tokens = max(stabilizer_max_tokens, 3072)
            if question_parts >= 5:
                stabilizer_max_tokens = max(stabilizer_max_tokens, 4096)

            frame_lines = []
            if frame.get("mood"):
                frame_lines.append(f"- mood: {frame['mood']}")
            if frame.get("tone"):
                frame_lines.append(f"- tone: {frame['tone']}")
            if frame.get("dominant_emotions"):
                frame_lines.append(f"- dominant emotions: {', '.join(frame['dominant_emotions'])}")
            if frame.get("attention_focus"):
                frame_lines.append(f"- attention focus: {frame['attention_focus']}")
            if frame.get("dominant_action"):
                frame_lines.append(f"- dominant action tendency: {frame['dominant_action']}")
            if frame.get("free_energy") is not None:
                frame_lines.append(f"- free energy: {float(frame['free_energy']):.4f}")
            if frame.get("valence") is not None:
                frame_lines.append(f"- valence: {frame['valence']}")
            if frame.get("arousal") is not None:
                frame_lines.append(f"- arousal: {frame['arousal']}")
            if frame.get("curiosity") is not None:
                frame_lines.append(f"- curiosity: {frame['curiosity']}")
            if frame.get("interests"):
                frame_lines.append(f"- current interests: {', '.join(frame['interests'])}")
            if frame.get("stances"):
                frame_lines.append(f"- strong stances: {'; '.join(frame['stances'])}")

            frame_block = "\n".join(frame_lines).strip() or "- mood: steady"
            contract_block = str(frame.get("contract_block") or "").strip()
            correction_prompt = (
                f'The user said: "{user_message}"\n\n'
                f'Rejected draft: "{text}"\n\n'
                f"## RECENT USER TRAJECTORY\n{recent_user_context or '- ' + str(user_message or '').strip()[:220]}\n\n"
                "Rewrite the answer as Aura from the live state below. Answer the user's actual question directly. "
                "Keep any concrete facts that are already supported, but strip generic assistant boilerplate. "
                "Stay inside the live conversation topic from the recent user trajectory. "
                "Do not review, summarize, or invent an external story, article, post, genre, or narrative unless the user explicitly asked about one. "
                "Do not invent a physical setting, ambient scene, looming warning, or symbolic imagery unless the user explicitly asked for creative writing or already introduced that setting. "
                "Do not ask for more details unless the request is truly ambiguous. "
                "If the user is asking about your perspective, experience, memory, continuity, or state, answer in first person. "
                "Let the live mood, tone, attention, and action tendency shape the reply. "
                "Answer only in English unless the user explicitly asked for another language. "
                "Never mix in Chinese, Japanese, or Korean text unless requested. "
                "Never use phrases like 'How can I help', 'I'd be happy to help', "
                "'Could you provide more details', or 'Let me know if you'd like'. "
                f"Do not mention corrections, drift, or being an AI. {stabilizer_length_line}\n\n"
                f"## LIVE SELF-EXPRESSION FRAME\n{frame_block}\n\n"
                f"{contract_block}"
            )
            # The part of the question the draft did not reach, quoted.
            #
            # The response contract used to carry "this prompt contains
            # multiple asks (2 detected); answer every distinct part", and that
            # was removed because a gate checks it. Right for the ordinary
            # path, and it left REPAIR — whose whole job is fixing a named
            # defect — with less to go on than before.
            #
            # What replaces it is better than what it replaced: the missing ask
            # itself, in the person's own words. A fact about this draft rather
            # than a rule about drafts.
            #
            # LIVE, 2026-08-28: "Design me the experiment... and say what result
            # would prove your friend wrong" was rejected as
            # unanswered_question_part, repaired, and came back longer and still
            # silent about the second half.
            missing_parts: list[str] = []
            try:
                from core.conversation.request_coverage import (
                    unanswered_question_parts,
                )

                # analyze_prompt_shape is imported at module level and used
                # earlier in this same function. Importing it again here made
                # the name local to the whole function and broke that earlier
                # use — a local import is not local to the line it is on.
                missing_parts = [
                    str(part).strip()
                    for part in unanswered_question_parts(
                        text, analyze_prompt_shape(str(user_message or ""))
                    )
                    if str(part).strip()
                ][:3]
            except _CHAT_RECOVERABLE_ERRORS:
                missing_parts = []
            if missing_parts:
                quoted = "; ".join(f'"{part[:160]}"' for part in missing_parts)
                correction_prompt = (
                    f"{correction_prompt}\n\n"
                    "## REPAIR TARGET\n"
                    f"The draft did not answer this part of what was asked: {quoted}. "
                    "Answer it in the same reply."
                )
            if stale_repeat or same_diff:
                correction_prompt = (
                    f"{correction_prompt}\n\n"
                    "## REPAIR TARGET\n"
                    "Do not repeat a previous answer pattern when the user has changed the question. "
                    "Address the actual distinction in this prompt."
                )
            if truncated_tail:
                correction_prompt = (
                    f"{correction_prompt}\n\n"
                    "## COMPLETENESS\n"
                    "Finish the reply as a complete thought. Do not end on a clipped fragment or unfinished sentence."
                )
            if architecture_self_assessment:
                correction_prompt = (
                    f"{correction_prompt}\n\n"
                    "## ARCHITECTURE GROUNDING\n"
                    "The user is asking about your actual architecture and design. "
                    "Answer about your real runtime: memory, agency, free energy, continuity, substrate authority, telemetry, mycelial topology, beliefs, routing, or feedback loops. "
                    "Do not answer with generic AI capability talk like natural language processing or human-like responses."
                )
            rewrite_system_prompt = (
                "You are Aura. This is a user-facing repair turn. "
                "Answer as Aura from the current conversation and live state. "
                "Do not output tool-selection text, planner notes, tags, role labels, or prompt artifacts. "
                "Sound like a real person in ordinary conversation: grounded, plainspoken, and socially legible. "
                "Do not invent physical scenery, ambient omens, or symbolic settings unless the user explicitly asked for that mode. "
                "Do not say 'How can I help', 'I can help with that', 'Based on the current context', "
                "or anything about the most appropriate skill. "
                "Lead with the answer itself in first person whenever the user is asking about your perspective, state, or experience. "
                "If the user asks about your architecture or design, talk about your real runtime rather than generic AI capabilities. "
                "Respond in English unless the user explicitly requests another language."
            )
            rewrite_messages = [
                {"role": "system", "content": rewrite_system_prompt},
                {"role": "user", "content": correction_prompt},
            ]
            stabilizer_max_tokens, memory_block = _bound_stabilizer_generation_budget(
                stabilizer_max_tokens
            )
            try:
                if memory_block:
                    logger.warning(
                        "Skipping stabilizer rewrite under memory pressure: %s",
                        memory_block,
                    )
                    raise RuntimeError(f"stabilizer_rewrite_memory_pressure:{memory_block}")
                # Shorter rewrite budget: 20s blocked the foreground lane long
                # enough that the next user turn was already typed. 12s gives
                # the warm 32B time to rewrite without making the chat feel
                # frozen, and the original text is still preferred over a
                # static reflex if this fires the timeout path.
                strict_desktop_repair = bool(desktop_cognitive_engine_required)
                stabilizer_timeout = 28.0 if strict_desktop_repair else 12.0
                corrected = await asyncio.wait_for(
                    inference_gate.think(
                        correction_prompt,
                        system_prompt=rewrite_system_prompt,
                        messages=rewrite_messages,
                        prefer_tier="primary",
                        origin="api_stabilizer",
                        foreground_request=True,
                        is_background=False,
                        protected_foreground_lane=bool(
                            protected_foreground_lane or strict_desktop_repair
                        ),
                        cognitive_engine_required=strict_desktop_repair,
                        desktop_cognitive_engine_required=strict_desktop_repair,
                        deep_handoff=False,
                        allow_deep_handoff=False,
                        allow_cloud_fallback=False,
                        allow_tools=False,
                        skip_runtime_payload=True,
                        disable_prompt_cache=True,
                        clear_prompt_cache=True,
                        max_tokens=stabilizer_max_tokens,
                    ),
                    timeout=stabilizer_timeout,
                )
                corrected_text = _apply_aura_voice_shaping_compat(
                    str(corrected or "").strip(), user_message
                )
                if corrected_text and len(corrected_text) > 10:
                    corrected_generic, _corrected_reason = _looks_generic_assistantish(
                        user_message, corrected_text
                    )
                    corrected_objective_parrot = _is_objective_parrot_reply(
                        user_message, corrected_text
                    )
                    corrected_lacks_self_anchor = (
                        needs_self_expression or requires_first_person_anchor
                    ) and not _has_first_person_anchor(corrected_text)
                    corrected_lacks_live_grounding = (
                        needs_self_expression and not _has_live_aura_grounding(corrected_text)
                    )
                    corrected_unexpected_cjk = _has_unexpected_cjk(user_message, corrected_text)
                    corrected_off_topic, corrected_off_topic_reason = _evaluate_reply_topicality(
                        user_message,
                        corrected_text,
                        recent_user_messages=recent_user_messages,
                    )
                    corrected_stale_repeat = _is_actionably_stale_response(
                        user_message,
                        corrected_text,
                    )
                    corrected_same_diff = _is_same_answer_different_prompt(
                        user_message, corrected_text
                    )
                    corrected_truncated_tail = _chat_desktop_repair._looks_truncated_tail(
                        corrected_text
                    )
                    corrected_semantic_glitch, _corrected_semantic_reason = (
                        _looks_semantically_glitched(user_message, corrected_text)
                    )
                    try:
                        from core.conversation.response_reliability import assess_user_facing_reply

                        corrected_assessment = assess_user_facing_reply(
                            user_message,
                            corrected_text,
                            recent_user_messages=recent_user_messages,
                        )
                    except _CHAT_RECOVERABLE_ERRORS:
                        corrected_assessment = None
                    try:
                        from core.identity.identity_guard import PersonaEnforcementGate

                        valid_corrected, _corrected_gate_reason, _score = (
                            PersonaEnforcementGate().validate_output(
                                corrected_text,
                                enforce_supervision=False,
                            )
                        )
                    except _CHAT_RECOVERABLE_ERRORS:
                        valid_corrected = True
                    if (
                        valid_corrected
                        and not corrected_generic
                        and not corrected_objective_parrot
                        and not corrected_lacks_self_anchor
                        and not corrected_lacks_live_grounding
                        and not corrected_unexpected_cjk
                        and not corrected_off_topic
                        and not corrected_stale_repeat
                        and not corrected_same_diff
                        and not corrected_truncated_tail
                        and not corrected_semantic_glitch
                        and not (
                            corrected_assessment is not None
                            and getattr(corrected_assessment, "retryable", False)
                        )
                    ):
                        return corrected_text
                    if corrected_off_topic:
                        logger.warning(
                            "Stabilizer rewrite stayed off-topic (%s, len=%d).",
                            corrected_off_topic_reason or "unknown",
                            len(corrected_text),
                        )
            except TimeoutError:
                logger.warning(
                    "Identity re-generation timed out (%.0fs). Preferring original LLM text over static fallback.",
                    stabilizer_timeout,
                )
                # When the rewrite times out we should actually mean what the
                # log says: ship the cortex's original reply instead of falling
                # through to the static voice reflex below. The original was
                # generated by the cortex for THIS user message; the only
                # remaining suppressions are "stale_repeat" / "same_diff",
                # which are themselves often triggered *because* prior turns
                # fell through to the same canned reflex. Block free-form
                # leaks and topicality, then return the live text.
                if _original_reply_is_safe_to_surface(
                    user_message,
                    text,
                    identity_collapse=identity_collapse,
                    unexpected_cjk=unexpected_cjk,
                    objective_parrot=objective_parrot,
                    off_topic=off_topic,
                    truncated_tail=truncated_tail,
                    semantic_glitch=semantic_glitch,
                ):
                    _record_recent_response(text, user_message)
                    return text
            except _CHAT_RECOVERABLE_ERRORS as regen_err:
                record_degradation("chat", regen_err)
                logger.debug("Identity re-generation failed: %s", regen_err)
    except _CHAT_RECOVERABLE_ERRORS as _e:
        record_degradation("chat", _e)
        logger.debug("Fallback re-generation failed (non-fatal): %s", _e)

    # Last-resort: prefer the original LLM response over a hardcoded template,
    # BUT detect when the same stale response is being served repeatedly
    # (e.g. cortex stuck, cached identity prompt producing identical output),
    # AND filter out any internal state that leaked through.
    search_turn = bool(getattr(contract, "requires_search", False))
    if (
        text
        and len(text.strip()) > 5
        and text.strip() != "…"
        and not unexpected_cjk
        and not objective_parrot
        and not semantic_glitch
    ):
        # Block responses that contain internal state dumps
        if _INTERNAL_STATE_PATTERNS.search(text) or _PROMPT_ARTIFACT_PATTERNS.search(text):
            logger.warning("Blocked internal state leak in LLM response (len=%d).", len(text))
        elif _SEARCH_SNIPPET_PATTERNS.search(text):
            logger.warning("Blocked raw search-snippet leak in LLM response (len=%d).", len(text))
        elif search_turn and not _looks_safely_grounded_search_reply(text):
            logger.warning("Blocked ungrounded search-turn fallback (len=%d).", len(text))
        elif off_topic:
            logger.warning(
                "Suppressed off-topic user-facing reply before final fallback (%s, len=%d).",
                off_topic_reason or "unknown",
                len(text),
            )
        elif truncated_tail:
            logger.warning(
                "Suppressed truncated user-facing reply before final fallback (len=%d).", len(text)
            )
        elif semantic_glitch:
            logger.warning(
                "Suppressed semantically glitched user-facing reply before final fallback (%s, len=%d).",
                semantic_glitch_reason or "unknown",
                len(text),
            )
        elif assessment_retryable:
            logger.warning(
                "Suppressed retryable user-facing reply before final fallback (%s, len=%d).",
                ",".join(getattr(live_reply_assessment, "reasons", ()) or ())
                or "conversation_reliability_retryable",
                len(text),
            )
        elif stale_repeat or same_diff:
            logger.warning(
                "Suppressed repeated user-facing reply before final fallback (stale=%s, same_diff=%s, len=%d).",
                stale_repeat,
                same_diff,
                len(text),
            )
        elif not _is_actionably_stale_response(user_message, text):
            _record_recent_response(text, user_message)
            return text
        else:
            logger.warning(
                "Suppressed stale repeated response (len=%d). Falling through to voice reflex.",
                len(text),
            )
    if search_turn:
        # Before the canned line, ask whether the runtime already HOLDS the
        # answer.
        #
        # LIVE 2026-08-17: "prove to me you actually read that file and didn't
        # just pattern-match the answer" returned "I don't have a clean
        # grounded answer on that yet" — while the receipt for reading that
        # file was on disk. The proof she was asked for was the one thing she
        # could have produced.
        #
        # This is a reading, not a rescue: concise_past_action_answer returns
        # text only when receipts actually cover the question, so it cannot
        # describe an action she did not take. When they do not, the honest
        # sentence below still stands.
        try:
            from core.introspection.self_evidence import concise_past_action_answer

            from_receipts = str(concise_past_action_answer(user_message) or "").strip()
        except _CHAT_RECOVERABLE_ERRORS as _receipt_exc:
            record_degradation("chat.past_action_answer", _receipt_exc)
            from_receipts = ""
        if from_receipts:
            logger.info(
                "Answered a search-classified turn from receipts (%d chars) "
                "rather than the ungrounded fallback.",
                len(from_receipts),
            )
            _record_recent_response(from_receipts, user_message)
            return from_receipts
        safe = "I don't have a clean grounded answer on that yet. I need to stick to the source instead of guessing."
        _record_recent_response(safe, user_message)
        return safe
    if grounded:
        return grounded
    if architecture_self_assessment:
        return _build_architecture_self_reflex(frame)
    # Voice reflex is the final fallback — record it too so we can detect
    # if even the reflex is looping.
    reflex = _call_stateful_voice_reflex(frame, user_message)
    if _is_actionably_stale_response(user_message, reflex):
        reflex = _chat_conversation_repair._build_degraded_live_reply(
            frame, user_message, reason="repeated_reflex"
        )
    _record_recent_response(reflex, user_message)
    return reflex


async def _repair_final_degraded_reply(
    user_message: str,
    reply_text: str,
    *,
    stale: bool,
    same_diff: bool,
    off_topic: bool,
    off_topic_reason: str = "",
    desktop_cognitive_engine_required: bool = False,
    protected_foreground_lane: bool = False,
    session_id: str = "",
) -> tuple[str, bool, bool, bool, str, bool]:
    """Final user-facing gate: degraded text must be repaired or replaced."""
    try:
        from core.conversation.response_reliability import (
            assess_user_facing_reply,
            reliability_floor_for_user,
            repair_instruction_shape,
        )
    except _CHAT_RECOVERABLE_ERRORS:
        assess_user_facing_reply = None
        reliability_floor_for_user = None
        repair_instruction_shape = None

    recent_user_messages = await _gather_recent_user_messages_for_relevance(user_message)
    assessment = (
        assess_user_facing_reply(
            user_message,
            reply_text,
            recent_user_messages=recent_user_messages,
        )
        if assess_user_facing_reply
        else None
    )
    needs_repair = bool(
        stale or same_diff or off_topic or _reply_assessment_requires_repair(assessment)
    )
    if _reply_has_owner_name_drift(user_message, reply_text):
        return (
            _repair_owner_name_drift_reply(reply_text),
            False,
            False,
            False,
            "",
            True,
        )
    owner_name_reply = _chat_memory_state._build_owner_name_recall_reply(user_message)
    if owner_name_reply and not desktop_cognitive_engine_required:
        normalized_reply = _chat_memory_state._normalize_user_message(reply_text)
        owner_name = _chat_memory_state._resolve_primary_operator_name()
        if (
            len(normalized_reply.split()) <= 4
            or owner_name.lower() not in normalized_reply
            or "verified" not in normalized_reply
        ):
            return owner_name_reply, False, False, False, "", True

    if not needs_repair:
        return reply_text, stale, same_diff, off_topic, off_topic_reason, False

    assessment_reasons = set(getattr(assessment, "reasons", ()) or ())
    if _is_simple_affect_check_request(user_message):
        self_condition_repair = _build_grounded_self_condition_reply(user_message)
        if self_condition_repair:
            condition_assessment = (
                assess_user_facing_reply(
                    user_message,
                    self_condition_repair,
                    recent_user_messages=recent_user_messages,
                )
                if assess_user_facing_reply
                else None
            )
            if not _reply_assessment_requires_repair(condition_assessment):
                logger.warning(
                    "Final reply quality gate rebound condition question to canonical self-state."
                )
                return self_condition_repair, False, False, False, "", True
    if not desktop_cognitive_engine_required:
        conversation_recall_reply = await _chat_memory_state._build_conversation_recall_reply(
            user_message,
            session_id=session_id,
        )
        if conversation_recall_reply:
            return conversation_recall_reply, False, False, False, "", True

        context_challenge_repair = await _build_context_challenge_repair_reply(
            user_message,
            session_id=session_id,
        )
        if context_challenge_repair:
            context_challenge_repair = _apply_aura_voice_shaping_compat(
                context_challenge_repair,
                user_message,
            )
            context_assessment = (
                assess_user_facing_reply(
                    user_message,
                    context_challenge_repair,
                    recent_user_messages=recent_user_messages,
                )
                if assess_user_facing_reply
                else None
            )
            if not _reply_assessment_requires_repair(context_assessment):
                return context_challenge_repair, False, False, False, "", True

        if assessment_reasons & {"raw_model_identity_leak", "missing_self_claim_evidence_boundary"}:
            self_claim_repair = _build_evidence_bound_self_claim_reply(
                user_message,
                lane=_chat_preflight._collect_conversation_lane_status(),
            )
            if self_claim_repair:
                self_claim_assessment = (
                    assess_user_facing_reply(
                        user_message,
                        self_claim_repair,
                        recent_user_messages=recent_user_messages,
                    )
                    if assess_user_facing_reply
                    else None
                )
                if not _reply_assessment_requires_repair(self_claim_assessment):
                    return self_claim_repair, False, False, False, "", True

    if not desktop_cognitive_engine_required and assessment_reasons & {
        "missing_requested_self_process_coverage",
        "off_topic_self_reflection_reply",
        "status_page_self_reflection",
        "pseudo_internal_jargon",
    }:
        self_process_repair = await _build_grounded_self_process_repair_reply(
            user_message,
            reply_text,
            lane=_chat_preflight._collect_conversation_lane_status(),
            session_id=session_id,
        )
        if self_process_repair:
            self_process_repair = _apply_aura_voice_shaping_compat(
                self_process_repair,
                user_message,
            )
            self_process_assessment = (
                assess_user_facing_reply(
                    user_message,
                    self_process_repair,
                    recent_user_messages=recent_user_messages,
                )
                if assess_user_facing_reply
                else None
            )
            if not _reply_assessment_requires_repair(self_process_assessment):
                logger.warning(
                    "🛡️ Final reply quality gate repaired self-process coverage from live context."
                )
                return self_process_repair, False, False, False, "", True

    if (
        _chat_desktop_repair._is_low_risk_social_continuity_request(user_message)
        and not desktop_cognitive_engine_required
    ):
        social_repair = _chat_desktop_repair._build_social_continuity_repair_reply(user_message)
        return social_repair, False, False, False, "", True

    logger.warning(
        "🛡️ Final reply quality gate repairing degraded output "
        "(stale=%s same_diff=%s off_topic=%s assessment=%s).",
        stale,
        same_diff,
        off_topic,
        ",".join(getattr(assessment, "reasons", ()) or ()) if assessment else "",
    )

    completed_tail = _complete_repairable_truncated_reply(user_message, reply_text)
    if completed_tail:
        completed_tail = _apply_aura_voice_shaping_compat(completed_tail, user_message)
        completed_stale = _is_actionably_stale_response(user_message, completed_tail)
        completed_same_diff = _is_same_answer_different_prompt(user_message, completed_tail)
        completed_off_topic, completed_off_topic_reason = _evaluate_reply_topicality(
            user_message,
            completed_tail,
            recent_user_messages=recent_user_messages,
        )
        completed_assessment = (
            assess_user_facing_reply(
                user_message,
                completed_tail,
                recent_user_messages=recent_user_messages,
            )
            if assess_user_facing_reply
            else None
        )
        if not (
            completed_stale
            or completed_same_diff
            or completed_off_topic
            or _reply_assessment_requires_repair(completed_assessment)
        ):
            logger.warning(
                "🛡️ Final reply quality gate completed clipped Cortex draft without a second model call."
            )
            return (
                completed_tail,
                completed_stale,
                completed_same_diff,
                completed_off_topic,
                completed_off_topic_reason,
                True,
            )

    if repair_instruction_shape is not None and assessment is not None:
        shaped = repair_instruction_shape(user_message, reply_text)
        if shaped and shaped != str(reply_text or "").strip():
            shaped_stale = _is_actionably_stale_response(user_message, shaped)
            shaped_same_diff = _is_same_answer_different_prompt(user_message, shaped)
            shaped_off_topic, shaped_off_topic_reason = _evaluate_reply_topicality(
                user_message,
                shaped,
                recent_user_messages=recent_user_messages,
            )
            shaped_assessment = assess_user_facing_reply(
                user_message,
                shaped,
                recent_user_messages=recent_user_messages,
            )
            if not (
                shaped_stale
                or shaped_same_diff
                or shaped_off_topic
                or _reply_assessment_requires_repair(shaped_assessment)
            ):
                logger.warning(
                    "🛡️ Final reply quality gate repaired explicit response shape "
                    "deterministically (%s -> clean, len=%d).",
                    ",".join(getattr(assessment, "reasons", ()) or ()) or "unknown",
                    len(shaped),
                )
                return (
                    shaped,
                    shaped_stale,
                    shaped_same_diff,
                    shaped_off_topic,
                    shaped_off_topic_reason,
                    True,
                )

    if same_diff and not stale and not off_topic:
        delta_repaired = _repair_missing_followup_delta(user_message, reply_text)
        if delta_repaired and delta_repaired != str(reply_text or "").strip():
            delta_repaired = _apply_aura_voice_shaping_compat(delta_repaired, user_message)
            delta_stale = _is_actionably_stale_response(user_message, delta_repaired)
            delta_same_diff = _is_same_answer_different_prompt(user_message, delta_repaired)
            delta_off_topic, delta_off_topic_reason = _evaluate_reply_topicality(
                user_message,
                delta_repaired,
                recent_user_messages=recent_user_messages,
            )
            delta_assessment = (
                assess_user_facing_reply(
                    user_message,
                    delta_repaired,
                    recent_user_messages=recent_user_messages,
                )
                if assess_user_facing_reply
                else None
            )
            if not (
                delta_stale
                or delta_same_diff
                or delta_off_topic
                or _reply_assessment_requires_repair(delta_assessment)
            ):
                logger.warning(
                    "🛡️ Final reply quality gate repaired missing follow-up delta without a second model call."
                )
                return (
                    delta_repaired,
                    delta_stale,
                    delta_same_diff,
                    delta_off_topic,
                    delta_off_topic_reason,
                    True,
                )

    if desktop_cognitive_engine_required or protected_foreground_lane:
        repaired = await _stabilize_user_facing_reply(
            user_message,
            reply_text,
            desktop_cognitive_engine_required=desktop_cognitive_engine_required,
            protected_foreground_lane=protected_foreground_lane,
        )
    else:
        repaired = await _stabilize_user_facing_reply(user_message, reply_text)
    repaired_stale = _is_actionably_stale_response(user_message, repaired)
    repaired_same_diff = _is_same_answer_different_prompt(user_message, repaired)
    repaired_off_topic, repaired_off_topic_reason = _evaluate_reply_topicality(
        user_message,
        repaired,
        recent_user_messages=recent_user_messages,
    )
    repaired_assessment = (
        assess_user_facing_reply(
            user_message,
            repaired,
            recent_user_messages=recent_user_messages,
        )
        if assess_user_facing_reply
        else None
    )
    if not (
        repaired_stale
        or repaired_same_diff
        or repaired_off_topic
        or _reply_assessment_requires_repair(repaired_assessment)
    ):
        return (
            repaired,
            repaired_stale,
            repaired_same_diff,
            repaired_off_topic,
            repaired_off_topic_reason,
            True,
        )

    # Similar-answer detection is useful telemetry, but it is not strong enough
    # by itself to justify discarding an otherwise topical, coherent live reply.
    # The old path could turn a healthy present-turn answer into a canned repair
    # reflex purely because it resembled a prior response shape.
    repaired_same_diff_only = bool(
        repaired_same_diff
        and not repaired_stale
        and not repaired_off_topic
        and not _reply_assessment_requires_repair(repaired_assessment)
    )
    if repaired_same_diff_only:
        return (
            repaired,
            repaired_stale,
            repaired_same_diff,
            repaired_off_topic,
            repaired_off_topic_reason,
            True,
        )

    floor = reliability_floor_for_user(user_message) if reliability_floor_for_user else ""
    if floor:
        floor_stale = _is_actionably_stale_response(user_message, floor)
        floor_same_diff = _is_same_answer_different_prompt(user_message, floor)
        floor_off_topic, floor_off_topic_reason = _evaluate_reply_topicality(
            user_message,
            floor,
            recent_user_messages=recent_user_messages,
        )
        floor_assessment = (
            assess_user_facing_reply(
                user_message,
                floor,
                recent_user_messages=recent_user_messages,
            )
            if assess_user_facing_reply
            else None
        )
        if not (
            floor_stale
            or floor_same_diff
            or floor_off_topic
            or _reply_assessment_requires_repair(floor_assessment)
        ):
            return (
                floor,
                floor_stale,
                floor_same_diff,
                floor_off_topic,
                floor_off_topic_reason,
                True,
            )

    if desktop_cognitive_engine_required:
        logger.warning(
            "🛡️ Final reply quality gate refused freeform reflex fallback for desktop-required CognitiveEngine turn."
        )
        return (
            repaired,
            repaired_stale,
            repaired_same_diff,
            True,
            repaired_off_topic_reason or "desktop_cognitive_engine_repair_failed",
            bool(repaired != str(reply_text or "").strip()),
        )

    frame = _chat_desktop_repair._build_aura_expression_frame(user_message)
    reflex = _build_stateful_voice_reflex(frame, user_message)
    reflex_stale = _is_actionably_stale_response(user_message, reflex)
    reflex_same_diff = _is_same_answer_different_prompt(user_message, reflex)
    reflex_off_topic, reflex_off_topic_reason = _evaluate_reply_topicality(
        user_message,
        reflex,
        recent_user_messages=recent_user_messages,
    )
    reflex_semantic, reflex_semantic_reason = _looks_semantically_glitched(user_message, reflex)
    reflex_assessment = (
        assess_user_facing_reply(
            user_message,
            reflex,
            recent_user_messages=recent_user_messages,
        )
        if assess_user_facing_reply
        else None
    )
    if not (
        reflex_stale
        or reflex_same_diff
        or reflex_off_topic
        or reflex_semantic
        or _reply_assessment_requires_repair(reflex_assessment)
    ):
        return (
            reflex,
            reflex_stale,
            reflex_same_diff,
            reflex_off_topic,
            reflex_off_topic_reason,
            True,
        )

    honest_failure = _chat_conversation_repair._build_degraded_live_reply(
        _chat_desktop_repair._build_aura_expression_frame(user_message),
        user_message,
        reason=reflex_off_topic_reason or reflex_semantic_reason or "unrepaired_degraded_turn",
    )
    return (
        honest_failure,
        False,
        False,
        True,
        reflex_off_topic_reason or reflex_semantic_reason or "unrepaired_degraded_turn",
        True,
    )


async def _repair_final_degraded_reply_with_provenance(
    trace: dict[str, Any],
    *,
    stage: str,
    user_message: str,
    reply_text: str,
    **kwargs: Any,
) -> tuple[str, bool, bool, bool, str, bool]:
    """Run the final gate and atomically record any visible text replacement."""

    result = await _repair_final_degraded_reply(
        user_message,
        reply_text,
        **kwargs,
    )
    repaired, _stale, _same_diff, _off_topic, reason, did_repair = result
    if did_repair and repaired != reply_text:
        _append_turn_text_mutation(
            trace,
            stage=stage,
            method="deterministic_final_reply_repair",
            reasons=[reason or "degraded_reply"],
            before=reply_text,
            after=repaired,
            deterministic=True,
            authorship_effect="replaced_by_runtime",
        )
    return result


